module TX(clk, rst, botao, instrucao, dado, info_saida);

   input [3:0]dado;
	input [3:0]instrucao;
   input botao;
   input clk, rst;
   output reg info_saida;

   reg [2:0]estado;
   reg [3:0]contador;

   parameter INICIO = 3'b000, 
             ESPERA = 3'b001,
             EXTREMO = 3'b010,
             ENVIA_DADO = 3'b011,
             ENVIA_INSTRUCAO = 3'b100;

   initial begin
       info_saida = 1'd1;
       estado = INICIO;
       contador = 4'd0;
   end

   always@(*) begin
       case(estado)
           INICIO: begin
               info_saida = 1;
            end
            ESPERA: begin
                info_saida = 1;
            end
            EXTREMO: begin
					info_saida = 0;
            end
            ENVIA_DADO: begin
                info_saida = dado[contador];
            end
            ENVIA_INSTRUCAO: begin
                info_saida = instrucao[contador - 4];
            end
            default: begin
                info_saida = info_saida;
            end

        endcase

    end

    always@(posedge clk or negedge rst) begin

        if(rst == 0) begin 
            estado = INICIO;
        end
        else begin
            case(estado)
                INICIO: begin
                    contador = 0;
                    if(botao == 1) begin
                        estado = ESPERA;
                    end
                end
                ESPERA: begin
                    if(botao == 0) begin
                        estado = EXTREMO;
                    end
                end
                EXTREMO: begin
                        estado = ENVIA_DADO;
                end
                ENVIA_DADO: begin
                    contador = contador + 1;
                    if(contador == 3) begin
                        estado = ENVIA_INSTRUCAO;
                    end
                end
                ENVIA_INSTRUCAO: begin 
                    contador = contador + 1;
                    if(contador == 7) begin
                        estado = INICIO;
                    end
                end
                default: begin
                    estado = estado;
                end
            endcase
        end
    end

endmodule

module HD
#(parameter BITS_TRILHA=4, parameter BITS_SETOR=6)
(
	//memoria com 64 slots de 32 bits
	input [31:0] dado_entr,
	input [(BITS_TRILHA-1):0] trilha,
   input [(BITS_SETOR-1):0] setor,
	input Sel_HD_Lei_Esc, read_clock, write_clock,
	output reg [31:0] saida
);
	localparam  NUM_SETORES=2**BITS_SETOR;

	// Declara o HD Simulado (1024 slots -> 16 trilhas e 64 setores)
	reg [31:0] hd_sim[((2**BITS_TRILHA)*(2**BITS_SETOR))-1:0];

	always @ (posedge write_clock)
	begin
		// Escrita no HD
		if (Sel_HD_Lei_Esc)
			hd_sim[trilha*NUM_SETORES + setor] = dado_entr;
	end

	always @ (posedge read_clock)
	begin
		// Leitura no HD
		saida = hd_sim[trilha*NUM_SETORES + setor];
	end

endmodule

