 /*
  * Only for testbenches, not synthesizable!
  * 
  * Use this in combination with frame_check to generate random packets with
  * random spaceing between them to check whether a user logic module 
  * forwards packets correctly.
  */
`timescale 1ns / 1ps
module frame_gen #(
    parameter C_INPORT_WIDTH = 3,
    parameter C_OUTPORT_WIDTH = 8,
    parameter C_PACKET_LENGTH_WIDTH = 14,
    parameter C_AXIS_DATA_WIDTH = 256, //currently hardcoded. if you want to change this remember to change m_axis_tdata generation too
    parameter C_MAX_PACKET_SIZE = 9000,
    parameter C_IN_PORT = 0,
    parameter C_IN_VPORT = 0,
    parameter C_OUT_PORT = 0,
    parameter C_OUT_VPORT = 0,
    parameter C_MAX_IDLE_CYCLES = 10
    )
    (

    // axi clock and reset //
    input clk,
    input axi_resetn,
    // Master Stream Ports
    output reg [C_AXIS_DATA_WIDTH-1:0] m_axis_tdata,
    output reg [(C_AXIS_DATA_WIDTH/8)-1:0] m_axis_tkeep,
    output reg [C_PACKET_LENGTH_WIDTH-1:0] m_axis_tuser_packet_length,
    output reg [C_INPORT_WIDTH-1:0] m_axis_tuser_in_port = C_IN_PORT,
    output reg [C_OUTPORT_WIDTH-1:0] m_axis_tuser_out_port = C_OUT_PORT,
    output reg [C_INPORT_WIDTH-1:0] m_axis_tuser_in_vport = C_IN_VPORT,
    output reg [C_OUTPORT_WIDTH-1:0] m_axis_tuser_out_vport = C_OUT_VPORT,
    output reg m_axis_tvalid=0,
    input m_axis_tready,
    output reg m_axis_tlast
    );
    `include "tkeep_coder.v"
    reg [31:0] seed;
    reg [C_AXIS_DATA_WIDTH-1:0] payload;
    reg [C_PACKET_LENGTH_WIDTH-1:0] tosend=0;
    reg [C_PACKET_LENGTH_WIDTH-1:0] length;
    reg [31:0] pkt_counter = 0;
    reg invert = 0;
    reg [31:0] sleep = 0;
    always @(posedge clk) begin
        if(tosend==0 && (sleep == 0 ) && (C_MAX_IDLE_CYCLES > 0 )) begin
            sleep = $unsigned($random) % C_MAX_IDLE_CYCLES;
            m_axis_tvalid = 0;
            m_axis_tlast = 0;

        if(sleep > 0 )
            sleep = sleep -1;
        if((m_axis_tvalid && m_axis_tready || !m_axis_tvalid) && sleep == 0) begin
            if ( tosend == 0) begin
                pkt_counter = pkt_counter + 1;
                seed = $unsigned($random);
                m_axis_tuser_packet_length = seed[C_PACKET_LENGTH_WIDTH-1:0] % C_MAX_PACKET_SIZE;
                if (m_axis_tuser_packet_length < 64) begin
                    m_axis_tuser_packet_length = 64;
                end
                tosend=m_axis_tuser_packet_length;
                m_axis_tdata = {pkt_counter,seed,~seed,seed,~seed,seed,~seed,seed};
                invert = 1;
            end else begin
                     if(invert)
                        m_axis_tdata = {~seed,seed,~seed,seed,~seed,seed,~seed,seed};
                     else
                        m_axis_tdata = {seed,~seed,seed,~seed,seed,~seed,seed,~seed};
                     invert = ~invert;
            end
            m_axis_tkeep = {(C_AXIS_DATA_WIDTH/8){1'b1}};
            if(tosend < (C_AXIS_DATA_WIDTH/8)) begin
                m_axis_tkeep = decode(tosend-1);
            end
            if(tosend<=(C_AXIS_DATA_WIDTH/8))
                m_axis_tlast = 1;
            else
                m_axis_tlast = 0;
               if(tosend >=(C_AXIS_DATA_WIDTH/8))
                tosend = tosend - (C_AXIS_DATA_WIDTH/8);
            else
                tosend = 0;
            m_axis_tvalid = 1;
        end
        if(axi_resetn) begin
            seed <= 0;
            payload <= 0;
            tosend <=0;
            length <=0;
            pkt_counter <= 0;
            invert <= 0;
            sleep <= 0;
        end
    end
endmodule

`timescale 1ns/1ps

module mips_txt;

	reg clk;
	reg reset;
	reg interrupt;

	wire [31:0] macroscopic_pc;

	wire [31:0] i_inst_addr;
	wire [31:0] i_inst_rdata;

	wire [31:0] m_data_addr;
	wire [31:0] m_data_rdata;
	wire [31:0] m_data_wdata;
	wire [3 :0] m_data_byteen;

	wire [31:0] m_inst_addr;

	wire		w_grf_we;
	wire [4 :0] w_grf_addr;
	wire [31:0] w_grf_wdata;

	wire [31:0] w_inst_addr;

	mips uut(
		.clk(clk),
		.reset(reset),
		.interrupt(interrupt),
		.macroscopic_pc(macroscopic_pc),

		.i_inst_addr(i_inst_addr),
		.i_inst_rdata(i_inst_rdata),

		.m_data_addr(m_data_addr),
		.m_data_rdata(m_data_rdata),
		.m_data_wdata(m_data_wdata),
		.m_data_byteen(m_data_byteen),

		.m_inst_addr(m_inst_addr),

		.w_grf_we(w_grf_we),
		.w_grf_addr(w_grf_addr),
		.w_grf_wdata(w_grf_wdata),

		.w_inst_addr(w_inst_addr)
	);

	initial begin
		clk <= 0;
		reset <= 1;
		interrupt <= 0;
		#20 reset <= 0;
	end

	integer i;
	reg [31:0] fixed_addr;
	reg [31:0] fixed_wdata;
	reg [31:0] data[0:4095];
	reg [31:0] inst[0:5119];

	// ----------- For Instructions -----------

	assign m_data_rdata = data[(m_data_addr >> 2) % 5120];
	assign i_inst_rdata = inst[((i_inst_addr - 32'h3000) >> 2) % 5120];

	initial begin
		$readmemh("code.txt", inst);
		for (i = 0; i < 5120; i = i + 1) data[i] <= 0;
	end

	// ----------- For Data Memory -----------

	always @(*) begin
		fixed_wdata = data[(m_data_addr >> 2) & 4095];
		fixed_addr = m_data_addr & 32'hfffffffc;
		if (m_data_byteen[3]) fixed_wdata[31:24] = m_data_wdata[31:24];
		if (m_data_byteen[2]) fixed_wdata[23:16] = m_data_wdata[23:16];
		if (m_data_byteen[1]) fixed_wdata[15: 8] = m_data_wdata[15: 8];
		if (m_data_byteen[0]) fixed_wdata[7 : 0] = m_data_wdata[7 : 0];
	end

	always @(posedge clk) begin
		if (reset) for (i = 0; i < 4096; i = i + 1) data[i] <= 0;
		else if (|m_data_byteen && fixed_addr >> 2 < 4096) begin
			data[fixed_addr >> 2] <= fixed_wdata;
			$display("%d@%h: *%h <= %h", $time, m_inst_addr, fixed_addr, fixed_wdata);
		end
	end

	// ----------- For Registers -----------

	always @(posedge clk) begin
		if (~reset) begin
			if (w_grf_we && (w_grf_addr != 0)) begin
				$display("%d@%h: $%d <= %h", $time, w_inst_addr, w_grf_addr, w_grf_wdata);
			end
		end
	end

	// ----------- For Interrupt -----------

	wire [31:0] fixed_macroscopic_pc;

	assign fixed_macroscopic_pc = macroscopic_pc & 32'hfffffffc;

	parameter exception_pc = 32'h00003018;

	integer exception_count;
	integer needInterrupt;

	initial begin
		needInterrupt = 0;
		exception_count = 0;

		$display("#exception@%h",exception_pc);

		$display("#interrupt@1");
		$display("#end@");
		#20 reset = 0;
	end

	always @(negedge clk) begin
		if (reset) begin
			needInterrupt = 0;
			interrupt = 0;
		end
		else begin
			if (interrupt) begin
				if (|m_data_byteen && fixed_addr == 32'h7F20) begin
					interrupt = 0;
				end
			end
			else if (needInterrupt) begin
				needInterrupt = 0;
				interrupt = 1;
			end
			else begin
				case (fixed_macroscopic_pc)
					exception_pc:
						begin
							if (exception_count == 0) begin
								exception_count = 1;
								interrupt = 1;
							end
						end
				endcase
			end
		end
	end

	always #2 clk <= ~clk;

endmodule

// Autor: Thaís Laura Anício Andrade
// 
// Data de criação:   16/06/2024 
// Nome do módulo:    BN
// Nome do projeto:   Projeto Final de Sistemas Digitais
// Versão: v2
// Descrição: Esse projeto utiliza o módulo ordenador, que possui diversos módulos básicos de ordenação (Basic Network - BN)
//            em paralelo, para ordenar oito números com Size bits de forma decrescente (y1 é o máximo, y8, o mínimo). 
// 			  Dentro de cada BN, existe um comparador e dois multiplexadores, os quais retornam o número 'max' e 'min'.
// 			  Todo o código foi escrito na linguagem de hardware Verilog, processado no programa Leonardo Spectrum.
//			  Em conjunto com os módulos, o projeto também estuda e compara a área, o delay e a quantidade de processamento
//			  em função da quantidade de bits das variáveis de input.


