                                {102{(~i_scan_mode)}} );

assign tx_en_bs[101:0] = jtag_mode_in ?
                         {102{1'b0}} :
                         ( tx_en[101:0] &
                          ~fault_stdby[101:0] &
                          {102{(~i_scan_mode)}} );

