// This module implements the pc090oj logic

module jtrastan_obj(
    input           rst,
    input           clk,
    input           pxl_cen,

    input           HS,
    input           flip,
    input    [8:0]  hdump,
    input    [8:0]  vrender,

    input    [10:1] main_addr,
    input    [15:0] main_dout,
    output   [15:0] main_din,
    input    [ 1:0] main_dsn,
    input           main_rnw,
    input           obj_cs,        // selection from address decoder
    output          dtackn,

    output reg [18:1] rom_addr,
    input    [31:0] rom_data,
    output          rom_cs,
    input           rom_ok,
    input    [ 7:0] debug_bus,
    output   [ 7:0] pxl,

    // NVRAM (debug) dump
    input    [10:0] ioctl_addr,
    output   [ 7:0] ioctl_din,
    input           ioctl_ram
);

wire [ 1:0] main_we;
wire [15:0] scan_dout;
reg  [15:0] attr, ypos, xpos, code;
reg         HSl;
reg  [ 7:0] obj_cnt;
reg         done, half, dr_busyl;
wire        last_obj;
reg         inzone, dr_busy, dr_start, cur_hflip, buf_we;
reg  [ 3:0] cur_pal;
reg  [ 2:0] scan_st, xcnt;
reg  [ 1:0] scan_cnt;
reg  [ 8:0] ydiff, buf_pos;
reg  [31:0] pxl_data;
wire [ 3:0] cur_pxl;

assign main_we = ~main_dsn & {2{obj_cs & ~main_rnw}};
assign last_obj = obj_cnt==0;
assign rom_cs = dr_busy;
assign cur_pxl = cur_hflip ? pxl_data[31:28] : pxl_data[3:0];
assign dtackn = 1;

always @* begin
    ydiff  = ypos[8:0] - (vrender-9'd8);
    inzone = ydiff<16;
end

// Scanner
always @() begin
    if( rst ) begin
        scan_st <= 0;
        obj_cnt <= 0;
        HSl     <= 0;
        done    <= 0;
        dr_start <= 0;
    end else begin
        HSl <= HS;
        dr_start <= 0;
        dr_busyl <= dr_busy;

        if( scan_st != 6 ) begin
            scan_st  <= scan_st + 3'd1;
            scan_cnt <= scan_cnt+ 2'd1;
        end
        case( scan_st )
            0:  if( !HS && HSl ) begin
                    obj_cnt <= 8'hff;
                    scan_cnt <= 0;
                    scan_st  <= 1;
                    done     <= 0;
                end else begin
                    scan_st <= 0;
                end
            2: attr <= scan_dout;
            3: ypos <= scan_dout;
            4: begin
                code <= scan_dout;
                obj_cnt <= obj_cnt-8'd1;
                done    <= last_obj;
            end
            5: begin
                xpos <= scan_dout;
                scan_cnt <= 0;
                if( !inzone ) begin
                    scan_st <= done ? 3'd0 : 3'd1;
                end
            end
            6: if( !dr_busy && !dr_busyl ) begin
                dr_start <= 1;
                scan_st  <= done ? 3'd0 : 3'd1;
            end
        endcase
    end
end

// Drawing
always @(posedge clk, posedge rst) begin
    if( rst ) begin
        dr_busy <= 0;
        buf_we  <= 0;
        half    <= 0;
        buf_pos <= 0;
        cur_pal <= 0;
        cur_hflip <= 0;
        rom_addr  <= 0;
        pxl_data  <= 0;
    end else begin
        if( dr_start ) begin
            rom_addr <= { code[12:0], ydiff[3:0]^{4{~attr[15]}}, attr[14] };
            half     <= 0;
            dr_busy  <= 1;
            buf_pos  <= xpos[8:0] + 9'd14;
            cur_pal  <= attr[3:0];
            cur_hflip<= attr[14];
            buf_we   <= 0;
        end
        if( dr_busy ) begin
            if( rom_cs && rom_ok && !buf_we) begin
                xcnt <= 7;
                pxl_data <= {
                    rom_data[27:24], rom_data[31:28],
                    rom_data[19:16], rom_data[23:20],
                    rom_data[11: 8], rom_data[15:12],
                    rom_data[ 3: 0], rom_data[ 7: 4] };
                buf_we <= 1;
            end
            if( buf_we ) begin
                rom_addr[1] <= ~cur_hflip;
                pxl_data <= cur_hflip ? pxl_data<<4: pxl_data>>4;
                xcnt     <= xcnt-3'd1;
                buf_pos  <= buf_pos+9'd1;
                if(xcnt==0) begin
                    buf_we<=0;
                    half  <=1;
                    if( half ) dr_busy <= 0;
                end
            end
        end
    end
end

jtframe_dual_nvram16 #(
    .SIMFILE_LO("obj_lo.bin"),
    .SIMFILE_HI("obj_hi.bin")
) u_ram(
    // Port 0
    .clk0   ( clk       ),
    .data0  ( main_dout ),
    .addr0  ( main_addr ),
    .we0    ( main_we   ),
    .q0     ( main_din  ),
    // Port 1
    .clk1   ( clk       ),
    .data1  (           ),
    .addr1a ( {obj_cnt,scan_cnt} ),
    .q1a    ( scan_dout ),
    // NVRAM dump
    .addr1b ( ioctl_addr),
    .sel_b  ( ioctl_ram ),
    .we1b   ( 1'd0      ),
    .q1b    ( ioctl_din )
);

jtframe_obj_buffer #(
    .DW     ( 8         ),
    .ALPHA  ( 0         )
) u_buffer(
    .clk    ( clk       ),
    .LHBL   ( ~HS       ),
    .flip   ( flip      ),
    // New data writes
    .wr_data( { cur_pal, cur_pxl} ),
    .wr_addr( buf_pos   ),
    .we     ( buf_we    ),
    // Old data reads (and erases)
    .rd_addr( hdump     ),
    .rd     ( pxl_cen   ),
    .rd_data( pxl[7:0]  )
);

endmodule

`timescale 1ns/1ps

module ProgramCounter(PC,clk,reset,PCplus4,ConBA,JT,DatabusA,ILLOP,XADR,ALUOut,PCSrc);
	output	[31:0]PC;
	input	clk;
	input	reset;
	input	[31:0]PCplus4;
	input	[31:0]ConBA;
	input	[25:0]JT;
	input	[31:0]DatabusA;
	input	[31:0]ILLOP;
	input	[31:0]XADR;
	input	ALUOut;
	input	[2:0]PCSrc;

	reg		[31:0]PC;
	wire	[31:0]addr1;
	assign	addr1 = (ALUOut == 0) ? PCplus4 : {PC[31],ConBA[30:0]};

	always@(posedge clk or negedge reset)
	begin
		if(~reset) PC = 32'h80000000;
		else
		begin
			case (PCSrc[2:0])
				0 : PC = PCplus4;
				1 : PC = addr1;
				2 : PC = {PC[31],3'b0,JT,2'b0};
				3 : PC = DatabusA;
				4 : PC = ILLOP;
				default : PC = XADR;
			endcase
		end
	end
endmodule

`include "mycpu.h"

module if_stage#(
    parameter TLBNUM = 16
)(
    input                            clk            ,
    input                            reset          ,
    //allwoin
    input                            ds_allowin     ,
    //brbus
    input  [`BR_BUS_WD        - 1:0] br_bus         ,
    //to ds
    output                           fs_to_ds_valid ,
    output [`FS_TO_DS_BUS_WD  - 1:0] fs_to_ds_bus   ,
    //from es
    input  [`ES_TO_FS_BUS_WD - 1 :0] es_to_fs_bus   ,
    //reflush
    input [`ES_REFLUSH_FS_WD  - 1:0] es_reflush_fs_bus,
    //inst_sram
    output        inst_sram_req,
    output        inst_sram_wr,
    output [ 1:0] inst_sram_size,
    output [ 3:0] inst_sram_wstrb,
    output [31:0] inst_sram_addr,
    output [31:0] inst_sram_wdata,
    input         inst_sram_addr_ok,
    input         inst_sram_data_ok,
    input  [31:0] inst_sram_rdata,
    // search port 0 
    output [              18:0] s0_vppn,
    output                      s0_va_bit12,//
    output [               9:0] s0_asid,
    input                       s0_found,
    input  [$clog2(TLBNUM)-1:0] s0_index,
    input  [              19:0] s0_ppn,//
    input  [               5:0] s0_ps,//
    input  [               1:0] s0_plv,//
    input  [               1:0] s0_mat,//
    input                       s0_d,//
    input                       s0_v
);
//br 
wire         br_stall;
wire         br_taken;
wire         br_taken_cancel;
wire [ 31:0] br_target;
//tlb
wire [ 5:0] tlb_ex_bus;
// pre_if stage
reg inst_sram_addr_ok_r;
wire pfs_ready_go;
wire pfs_to_fs_valid;
wire [31:0] next_pc;
wire [31:0] seq_pc;
wire [31:0] fs_vaddr;
assign pfs_ready_go = (inst_sram_addr_ok && inst_sram_req) || inst_sram_addr_ok_r || (|tlb_ex_bus);
assign pfs_to_fs_valid = pfs_ready_go;
assign inst_sram_req =  fs_allowin &&~reset && ~|tlb_ex_bus;
assign inst_sram_wr = 1'b0;
assign inst_sram_size = 2'b10;
assign inst_sram_wstrb = 4'b0;
assign inst_sram_wdata = 32'b0;
//assign inst_sram_addr = next_pc;
reg         fs_valid;
wire        fs_ready_go;


assign {br_stall, br_taken, br_taken_cancel, br_target} = br_bus;


wire        es_reflush_fs;
wire [31:0] ex_entry;
assign {es_reflush_fs, ex_entry} = es_reflush_fs_bus;

wire [31:0] csr_asid_rvalue;
wire [31:0] csr_crmd_rvalue;
wire [31:0] csr_dmw0_rvalue;
wire [31:0] csr_dmw1_rvalue;
assign {csr_crmd_rvalue, csr_dmw0_rvalue, csr_dmw1_rvalue, csr_asid_rvalue} = es_to_fs_bus;

wire [31:0] fs_inst;
reg [31:0] fs_pc;
wire inst_adef;

assign fs_to_ds_bus = {
                       tlb_ex_bus,
                       inst_adef,
                       fs_inst ,
                       fs_pc   };

reg        fs_inst_valid;
reg [31:0] fs_inst_buff;

reg fs_inst_cancel;

// IF stage
assign fs_ready_go    =  fs_inst_valid || (fs_valid && inst_sram_data_ok) || (|tlb_ex_bus);
assign fs_allowin     = !fs_valid || fs_ready_go && ds_allowin;
assign fs_to_ds_valid =  fs_valid && fs_ready_go && ~(br_taken&&~br_stall) && ~es_reflush_fs && ~fs_inst_cancel;
//error 6 br_taken
always @(posedge clk) begin
    if (reset) begin
        fs_valid <= 1'b0;
    end
    else if (fs_allowin) begin
        fs_valid <= pfs_to_fs_valid;
    end
    /*
    else if (br_taken_cancel) begin
        fs_valid <= 1'b0;
    end
    */
end

    always @(posedge clk) begin
        if(reset) begin
            inst_sram_addr_ok_r <= 1'b0;
        end
        else if(inst_sram_addr_ok && inst_sram_req && !fs_allowin) begin
            inst_sram_addr_ok_r <= 1'b1;
        end
        else if(fs_allowin) begin
            inst_sram_addr_ok_r <= 1'b0;
        end
    end

// ADEF
assign inst_adef = fs_valid & ((fs_pc[1:0] != 2'b0)||(next_pc[31] & (csr_crmd_rvalue[1:0]!=0)) & ~dmw_hit);

always @(posedge clk ) begin
    if(reset) begin
        fs_inst_valid <= 1'b0;
    end
    else if(!fs_inst_valid && inst_sram_data_ok && !fs_inst_cancel && !ds_allowin) begin
        fs_inst_valid <= 1'b1;
    end
    else if (ds_allowin || es_reflush_fs ) begin
        fs_inst_valid <= 1'b0;
    end

    if(reset) begin
        fs_inst_buff <= 32'b0;
    end
    else if(!fs_inst_valid && inst_sram_data_ok && !fs_inst_cancel && !ds_allowin) begin
        fs_inst_buff <= inst_sram_rdata;
    end
end


//inst_cancel
always @(posedge clk ) begin
    if(reset) begin
        fs_inst_cancel <= 1'b0;
    end
    else if(!fs_allowin && !fs_ready_go && ((es_reflush_fs) ||( br_taken && ~br_stall))) begin
        fs_inst_cancel <= 1'b1;
    end
    else if(inst_sram_data_ok) begin
        fs_inst_cancel <= 1'b0;
    end
end
    reg        br_taken_r;
    reg [31:0] br_target_r;
    //reflush
    reg        es_reflush_pfs_r;
    reg [31:0] ex_entry_r;
    always @(posedge clk) begin
        if(reset) begin
            br_taken_r <= 1'b0;
            br_target_r <= 32'b0;
        end
        else if(pfs_ready_go && fs_allowin)begin
            br_taken_r <= 1'b0;
            br_target_r <= 32'b0;
        end
        else if(br_taken && !br_stall) begin
            br_taken_r <= 1'b1;
            br_target_r <= br_target;
        end
    end
        //ex
    always @(posedge clk) begin
        if(reset) begin
            es_reflush_pfs_r <= 1'b0;
            ex_entry_r <= 32'b0;
        end
        else if(pfs_ready_go && fs_allowin)begin
            es_reflush_pfs_r <= 1'b0;
            ex_entry_r <= 32'b0;
        end
        else if(es_reflush_fs) begin
            es_reflush_pfs_r <= 1'b1;
            ex_entry_r <= ex_entry;
        end
    end

assign seq_pc=fs_pc+3'h4;
assign next_pc = es_reflush_pfs_r ? ex_entry_r : es_reflush_fs ? ex_entry : br_taken_r ? br_target_r : (br_taken && !br_stall) ? br_target : seq_pc;
always @(posedge clk ) begin
    if(reset) begin
        fs_pc <= 32'h1bfffffc;
    end
    else if(pfs_ready_go && fs_allowin) begin
        fs_pc <= next_pc;
    end
end
assign fs_inst = fs_inst_valid ? fs_inst_buff : inst_sram_rdata;
vaddr_transfer inst_transfer(
    .va        (next_pc),
    .inst_op   (3'b001),//{load.store,if}
    .pa        (inst_sram_addr),
    .tlb_ex_bus(tlb_ex_bus),//{PME,PPE,PIS,PIL,PIF,TLBR}
    //tlb
    .s_vppn    (s0_vppn),
    .s_va_bit12(s0_va_bit12),
    .s_asid    (s0_asid),
    .s_found   (s0_found),
    .s_index   (s0_index),
    .s_ppn     (s0_ppn),
    .s_ps      (s0_ps),
    .s_plv     (s0_plv),
    .s_mat     (s0_mat),
    .s_d       (s0_d),
    .s_v       (s0_v),
    //crmd
    .csr_asid  (csr_asid_rvalue),
    .csr_crmd  (csr_crmd_rvalue),
    //dmw
    .dmw_hit   (dmw_hit),
    .csr_dmw0  (csr_dmw0_rvalue),
    .csr_dmw1  (csr_dmw1_rvalue)

);
endmodule

