module tb_fifo;

	// Inputs
	reg clk;
	reg reset;
	reg sclr;
	reg wren;
	reg rden;
	reg [7:0] din;

	// Outputs
	wire full;
	wire empty;
	wire [7:0] dout;

	// Instantiate the Unit Under Test (UUT)
	fifo uut (
		.clk(clk), 
		.reset(reset), 
		.sclr(sclr), 
		.wren(wren), 
		.rden(rden), 
		.full(full), 
		.empty(empty), 
		.din(din), 
		.dout(dout)
	);

	initial begin
	 clk = 0;
	 #100   //reset delay
	 forever #30 clk = ~clk;


	integer errors;
	integer writeval;
	integer fd;
	integer count,status;
	reg[8*100:1] aline;

	integer i_sclr, i_wren, i_wdata, i_rden, i_rdata, i_full, i_empty;

	initial begin
		// Initialize Inputs
		#1
		clk = 0;
		reset = 1;
		sclr = 0;
		wren = 0;
		rden = 0;
		din = 0;
		errors = 0;
		count = 0;
		fd = $fopen("fifo_vectors.txt","r");

		// Wait 100 ns for global reset to finish
		#100;
		reset = 0;
		@(posedge clk);
		while ($fgets(aline,fd)) begin
		if (count != 0) begin
		 status = $sscanf(aline,"%x %x %x %x %x %x %x",i_sclr,i_wren, i_wdata, i_rden, i_rdata, i_full, i_empty);
		 sclr = i_sclr;
		 wren = i_wren;
		 din = i_wdata;
		 rden = i_rden;
		 @(negedge clk);
		 if (i_rden) begin
			if (i_rdata == dout) begin
			 $display("%d Pass: dout: %x",count,dout);
			end else begin
			 $display("%d FAIL: dout: %x(%x)",count,dout,i_rdata);
			 errors = errors+1;
			end
		 end //end if (i_rden)

		 if (i_full == full) $display("%d Pass: full: %x",count,full);
		 else begin
		  $display("%d FAIL: full: %x (%x)",count,full,i_full);
		   errors = errors+1;
		 end

		 if (i_empty == empty) $display("%d Pass: empty: %x",count,empty);
		 else begin
		  $display("%d FAIL: empty: %x (%x)",count,empty,i_empty);
		   errors = errors+1;
		 end


		end //end if (aline)

		count = count + 1;
		end //end while




		if (errors == 0) begin
			$display("(%t)PASSED: All vectors passed",$time());
		end else begin
		  $display("(%t)FAILED: %d vectors failed",$time(),errors);
		end

	end

endmodule

module cb (clk, reset, 
					 // for manually moving the tail
					 move_tail, tail_new, 
					 // en writes data, req reads data
					 din1_en, din2_en, dout1_req, dout2_req, 
					 // actual data i/o
					 din1, din2, dout1, dout2, 
					 // indicators for higher level to decide how/what to input
					 full, full_almost, 
					 // head and tail
					 head, tail);

	//synopsys template
	parameter CB_IDX = 4;
	parameter CB_WIDTH = 8;
	parameter CB_LENGTH = 1 << CB_IDX;

  input clk, reset, move_tail, din1_en, din2_en, dout1_req, dout2_req;
	input [CB_IDX-1:0] tail_new;
	input [CB_WIDTH-1:0] din1, din2;
	output reg full, full_almost;
	output reg [CB_WIDTH-1:0] dout1, dout2;
	output reg [CB_IDX-1:0] head, tail;

	// internal regs
	reg [CB_WIDTH-1:0] data [CB_LENGTH-1:0];
	reg [CB_WIDTH-1:0] next_data1, next_data2;
	reg [CB_IDX-1:0] next_head, next_tail;

	// i/o counter
	reg [CB_IDX:0] iocount;
	wire [CB_IDX:0] next_iocount;
	reg [1:0] incount, outcount;
	reg empty, empty_almost;

	// purely combinational
	wire [CB_IDX-1:0] tail_p1, tail_p2, head_p1, head_p2, cur_size;
	wire next_full, next_full_almost, next_empty, next_empty_almost;

	assign tail_p1 = tail + 1'd1;
	assign tail_p2 = tail + 2'd2;
	assign head_p1 = head + 1'd1;
	assign head_p2 = head + 2'd2;

	// need to keep track of the current buffer size
	assign cur_size = (next_tail>=next_head)? (next_tail - next_head) : (next_tail + CB_LENGTH - next_head);
	assign next_iocount = (move_tail)? cur_size : iocount + incount - outcount;
	assign next_full = next_iocount == CB_LENGTH;
	assign next_full_almost = next_iocount == (CB_LENGTH-1);
	assign next_empty = next_iocount == 0;
	assign next_empty_almost = next_iocount == 1;

	always @* begin
		// default cases
		next_data1 = data[tail];
		next_data2 = data[tail_p1];
		next_head = head;
		next_tail = tail;
		incount = 2'd0;
		outcount = 2'd0;
		dout1 = data[head];
		dout2 = data[head_p1];

		// deal with tail and data in
		if (move_tail) begin
			next_tail = tail_new;
		end else begin
			if (din1_en && !full) begin
				next_tail = tail_p1;
				next_data1 = din1;
				incount = 2'd1;
				if (din2_en && !full_almost) begin
					next_tail = tail_p2;
					next_data2 = din2;
					incount = 2'd2;
				end
			end
		end

		// deal with head and data out
		if (dout1_req && !empty) begin
			next_head = head_p1;
			outcount = 2'd1;
			if (dout2_req && !empty_almost) begin
				next_head = head_p2;
				outcount = 2'd2;
			end
		end
	end

	integer idx;
	//synopsys sync_set_reset "reset"
	always @(posedge clk) begin
		if (reset) begin
			head 					= `SD {CB_IDX{1'b0}};
			tail 					= `SD {CB_IDX{1'b0}};
			iocount 			= `SD {CB_IDX+1{1'b0}};
			full 					= `SD 1'b0;
			full_almost 	= `SD 1'b0;
			empty					= `SD 1'b0;
			empty_almost	= `SD 1'b0;

			for (idx=0;idx<CB_LENGTH;idx=idx+1) begin
				data[idx] = `SD 0;
			end

		end else begin
			data[tail]		= `SD next_data1;
			data[tail_p1] = `SD next_data2;
			head 					= `SD next_head;
			tail					= `SD next_tail;
			iocount 			= `SD next_iocount;
			full 					= `SD next_full;
			full_almost 	= `SD next_full_almost;
			empty					= `SD next_empty;
			empty_almost	= `SD next_empty_almost;
		end
	end

endmodule

// This program was cloned from: https://github.com/viktor-prutyanov/drec-fpga-intro
