/*
Módulo: BN

Descrição:
Esse módulo implementa um Basic Network de ordenação, retornando o maior e o menor valor entre as duas entradas. 
Utiliza outros dois módulos: comp_nbits e mux21.

Parâmetros:
- Size: quantidade de bits 
Output:
- max, min: o maior e o menor valor respectivamente
Input:
- A, B: valores a serem comparados

*/


`timescale 1 ns/100 ps

module BN #(parameter Size=8) (
    output [Size-1:0] max, min,
    input [Size-1:0] A, B
);

reg l;

    comp_nbits #(Size) u_comp (
        .it(l),
        .x(A),
        .y(B)
    );

	mux21 #(Size) u_max (
        .y(max),
        .s(l),
        .a1(B),
        .a0(A)
    );

	mux21 #(Size) u_min (
        .y(min),
        .s(l),
        .a1(A),
        .a0(B)
    );



endmodule

module bram(
    CLK,
    WE0,
    EN0,
    Di0,
    Do0,
    A0
)

    input   wire            CLK;
    input   wire    [3:0]   WE0;
    input   wire            EN0;
    input   wire    [31:0]  Di0;
    output  reg     [31:0]  Do0;
    input   wire    [31:0]   A0;

    // Define the size of BRAM
    parameter N = ;
    (* ram_style = "block" *) reg [31:0] RAM[0:2**N-1];


    always @(posedge CLK)
        if(EN0) begin
            Do0 <= RAM[A0[N-1:0]];
            if(WE0[0]) RAM[A0[N-1:0]][7:0] <= Di0[7:0];
            if(WE0[1]) RAM[A0[N-1:0]][15:8] <= Di0[15:8];
            if(WE0[2]) RAM[A0[N-1:0]][23:16] <= Di0[23:16];
            if(WE0[3]) RAM[A0[N-1:0]][31:24] <= Di0[31:24];
        end
        else
            Do0 <= 32'b0;
endmodule

