end
initial begin
  // rst=0;
  // #15 rst=1;
  // #10 ;
  #25;
  for(i=0;i<=16031;i=i+1)begin
    if((i!=0)&&(i%513==512))begin
      #(`CYCLE);
      in =0;
      in_nd=0;
      #(511*`CYCLE);
      // $display("t:%d in:%f",$time,in/32768.0);
