`default_nettype None

`timescale 1ns/1ps

module boothMultiplier4Bit(output reg[7:0] prod, output reg busy, input[3:0] mc, input[3:0] mp, input clk, input start);

    reg [3:0] A, Q, M;
    reg Q_1;
    reg [2:0] count;
    wire [3:0] sum, difference;

    always @(posedge clk) begin
        if (start) begin
            A <= 0;
            M <= mc;
            Q <= mp;
            Q_1 <= 1'b0;
            count <= 0;
        end
        else begin
            busy <= 1'b1;
            case ({Q[0], Q_1})
                2'b0_1 : {A, Q, Q_1} <= {sum[3], sum, Q};
                2'b1_0 : {A, Q, Q_1} <= {difference[3], difference, Q};
                default: {A, Q, Q_1} <= {A[3], A, Q};
            endcase
            count <= count + 1'b1;
            if(count == 4) begin
                busy <= 1'b0;
                prod <= {A, Q};
                count <= 0;
            end
        end
    end

    assign sum = A + M;
    assign difference = A + ~M + 1'b1;
endmodule

`timescale 1ns / 1ps

module TB;

    reg CLK, CLK_SYS, CLK_MUL, Reset;
	 wire CS, WE, CS_P;
	 reg [31:0] Data_BUS_READ, Prog_BUS_READ, writeBack;
    wire [31:0] ADDR, Data_BUS_WRITE, ADDR_Prog; 

    cpu DUT (
        .CLK(CLK),
        .Reset(Reset),
        .Data_BUS_READ(Data_BUS_READ),
        .Prog_BUS_READ(Prog_BUS_READ),
        .ADDR(ADDR),
        .Data_BUS_WRITE(Data_BUS_WRITE),
        .ADDR_Prog(ADDR_Prog),
        .CS(CS),
		  .WE(WE),
		  .CS_P(CS_P)
		     );

    initial begin

		$init_signal_spy("DUT/CLK_SYS","CLK_SYS",1);
		$init_signal_spy("DUT/CLK_MUL","CLK_MUL",1);
		$init_signal_spy("DUT/writeBack","writeBack",1);

		CLK = 0;
		Reset = 1;

		Data_BUS_READ = 32'h0;
		Prog_BUS_READ = 32'h0;

		#10 Reset = 0;


		#100000 $stop;
    end

    always #10 CLK = ~CLK;

endmodule

module L2(clock, CDB, CPUreceiver, selectedEmit)

input[21:0]CDB; //recebe mensagem do barramento comum
input[21:0]CPUreceiver; //recebe mensagem do processador
input clock;
reg[15:0]Data[3:0]; //armazena o dado, quando valido, do banco nos processadores
reg[2:0]Tag[3:0]; //armazena as tags presentes nos dois processadores
reg[1:0]Sharers[3:0]; //armazena quais processadores compartilham determinada tag, possui 1 quando o processador da posicao possui a tag
reg[1:0]State[3:0]; //guarda o estado de cada banco (linha)

wire[1:0]newState[3:0];
wire[3:0]soma;
wire[3:0]reset;
wire[3:0]clear;
wire[21:0]emit[3:0];
wire[21:0]pcEmit[1:0];

output reg[21:0]selectedEmit; //capaz de emitir dados no CDB

initial begin

	Data[0] = 16'b0000000000001010; //0010
	Data[1] = 16'b0000000000001000; //0008
	Data[2] = 16'b0000000001000100; //0068
	Data[3] = 16'b0000000000010010; //0018

	Tag[0] = 3'b000; //100 = Mem[0]
	Tag[1] = 3'b001; //108 = Mem[1]
	Tag[2] = 3'b110; //130 = Mem[6]
	Tag[3] = 3'b011; //118 = Mem[3]

	 //00=DI 01=DS 10=DM
	State[0] = 2'b10; //DM
	State[1] = 2'b01; //DS
	State[2] = 2'b10; //DM
	State[3] = 2'b01; //DS


	//[ P0?, P1? ]
	Sharers[0] = 2'b10;
	Sharers[1] = 2'b10;
	Sharers[2] = 2'b01;
	Sharers[3] = 2'b01;

	selectedEmit = 22'b1111111111111111111111;

end

StateMachineDir B0(clock, State[0], cdb, newState[0], emit[0], soma[0], reset[0], clear[0]);
StateMachineDir B1(clock, State[1], cdb, newState[1], emit[1], soma[1], reset[1], clear[1]);
StateMachineDir B2(clock, State[2], cdb, newState[2], emit[2], soma[2], reset[2], clear[2]);
StateMachineDir B3(clock, State[3], cdb, newState[3], emit[3], soma[3], reset[3], clear[3]);

PC0 pc00(clock, CDB, pcEmit[0], emitPC0, dataWB);
PC1 pc01(clock, CDB, pcEmit[1], emitPC1, dataWB);


always@(posedge clock)
begin
	selectedEmit = 22'b1111111111111111111111;

	if(CDB != 22'b1111111111111111111111)
	begin
		if(Tag[0] == CDB[15:13])
		begin
			State[0] = newState[0];
			if(soma[0] == 1'b1)
			begin
				Sharers[0][CDB[12]] = 1;
			end
			else if(reset[0] == 1'b1)
			begin
				Sharers[0][0] = 0;
				Sharers[0][1] = 0;
				Sharers[0][CDB[12]] = 1;
			end
			else if(clear[0] == 1'b1)
			begin
				Sharers[0][0] = 0;
				Sharers[0][1] = 0;
			end
			selectedEmit = {emit[0][21:16], Tag[0][3:0], CDB[12], 12'b0};
		end
		else if(Tag[1] == CDB[15:13])
		begin
			State[1] = newState[1];
			if(soma[1] == 1'b1)
			begin
				Sharers[1][CDB[12]] = 1;
			end
			else if(reset[1] == 1'b1)
			begin
				Sharers[1][0] = 0;
				Sharers[1][1] = 0;
				Sharers[1][CDB[12]] = 1;
			end
			else if(clear[1] == 1'b1)
			begin
				Sharers[1][0] = 0;
				Sharers[1][1] = 0;
			end
			selectedEmit = {emit[1][21:16], Tag[1][3:0], CDB[12], 12'b0};
		end
		else if(Tag[2] == CDB[15:13])
		begin
			State[2] = newState[2];
			if(soma[2] == 1'b1)
			begin
				Sharers[2][CDB[12]] = 1;
			end
			else if(reset[2] == 1'b1)
			begin
				Sharers[2][0] = 0;
				Sharers[2][1] = 0;
				Sharers[2][CDB[12]] = 1;
			end
			else if(clear[2] == 1'b1)
			begin
				Sharers[2][0] = 0;
				Sharers[2][1] = 0;
			end
			selectedEmit = {emit[2][21:16], Tag[2][3:0], CDB[12], 12'b0};
		end
		else if(Tag[3] == CDB[15:13])
		begin
			State[3] = newState[3];
			if(soma[3] == 1'b1)
			begin
				Sharers[3][CDB[12]] = 1;
			end
			else if(reset[3] == 1'b1)
			begin
				Sharers[3][0] = 0;
				Sharers[3][1] = 0;
				Sharers[3][CDB[12]] = 1;
			end
			else if(clear[3] == 1'b1)
			begin
				Sharers[3][0] = 0;
				Sharers[3][1] = 0;
			end
			selectedEmit = {emit[3][21:16], Tag[3][3:0], CDB[12], 12'b0};
		end
	end


end


endmodule

module vp_text_or_gfx #(
	// Character dimensions
	parameter CHAR_WIDTH        = 'd16,
	parameter CHAR_HEIGHT       = 'd20
) (
	// Base signals
	input wire clk,

	// Inputs
	input wire [31:0] charattr,
	input wire [4:0]  char_row_in,
	input wire [3:0]  ypos,
	input wire [6:0]  frame_count,
	input wire        enabled,

	// Common output
	output reg [4:0]  char_row_out,
	output reg [3:0]  foreground,
	output reg [3:0]  background,

	// Text output
	output reg [14:0] txt_font_address,
	output reg        txt_horz_size,
	output reg        txt_horz_part,
	output reg [15:0] txt_pattern,
	output reg [15:0] txt_border,
	output reg [1:0]  txt_func,
	output reg        txt_blink,
	output reg        txt_invert,
	output reg        txt_underline,
	output reg        txt_enable,

	// Graphic output
	output reg [19:0] gfx_bits,
	output reg        gfx_mosaic,
	output reg        gfx_enable
);

`include "constant.v"
`include "video_controller/horizontal_resize.v"
`include "video_controller/vertical_resize.v"
`include "video_controller/generate_pattern.v"

wire [3:0]  charattr_background    = charattr[31:28];
wire [3:0]  charattr_foreground    = charattr[27:24];
wire [3:0]  charattr_pattern       = charattr[23:20];
wire        charattr_border_left   = charattr[23];
wire        charattr_border_bottom = charattr[22];
wire        charattr_border_right  = charattr[21];
wire        charattr_border_top    = charattr[20];
wire [1:0]  charattr_function      = charattr[19:18];
wire        charattr_underline     = charattr[17];
wire        charattr_invert        = charattr[16];
wire [1:0]  charattr_blink         = charattr[15:14];
wire [3:0]  charattr_gfxmode       = charattr[13:10];
wire        charattr_part_vert     = charattr[13];
wire        charattr_part_horz     = charattr[12];
wire        charattr_size_vert     = charattr[11];
wire        charattr_size_horz     = charattr[10];
wire [9:0]  charattr_charcode      = charattr[9:0];

wire gfx_mode = charattr_gfxmode == 4'b0100 || charattr_gfxmode == 4'b1000;

wire draw_border = charattr_function == 2'b11;
wire top_border =
	char_row_in == 'd0 &&
	charattr_part_vert == FALSE &&
	charattr_border_top == TRUE;

wire bottom_border =
	char_row_in == 'd19 &&
	charattr_part_vert == charattr_size_vert &&
	charattr_border_bottom == TRUE;

always @(posedge clk) if (enabled) begin
	background <= charattr_background;
	foreground <= charattr_foreground;
	char_row_out <= char_row_in;

	txt_enable <= /* enabled & */~gfx_mode;
	gfx_enable <= /* enabled & */ gfx_mode;

	gfx_bits <= {
		charattr[23], charattr[22], charattr[21], charattr[20],
		charattr[19], charattr[18], charattr[17], charattr[16],
		charattr[15], charattr[14], charattr[ 9], charattr[ 8],
		charattr[ 7], charattr[ 6], charattr[ 5], charattr[ 4],
		charattr[ 3], charattr[ 2], charattr[ 1], charattr[ 0]
	};
	gfx_mosaic <= charattr[13];

	txt_font_address <=
		{ 1'b0, charattr_charcode, 4'b0 } +
		{ 3'b0, charattr_charcode, 2'b0 } +
		{
			10'b0,
			vertical_resize(
				charattr_size_vert, charattr_part_vert, char_row_in
			)
		};

	txt_underline <=
		charattr_underline &&
		char_row_in == 'd17 &&
		charattr_part_vert == charattr_size_vert;

	case (charattr_blink)
		2'b00: txt_blink <= FALSE;
		2'b01: txt_blink <= frame_count[6];
		2'b10: txt_blink <= frame_count[5];
		2'b11: txt_blink <= frame_count[4];
	endcase

	txt_invert <= charattr_invert;

	txt_horz_size <= charattr_size_horz;
	txt_horz_part <= charattr_part_horz;
	txt_pattern <= generate_pattern(charattr_pattern, ypos[3:0]);
	txt_func <= charattr_function;

	// Draw border
	if (draw_border) begin
		case ({ top_border | bottom_border, charattr_border_left, charattr_border_right, charattr_part_horz, charattr_size_horz })
			5'b00000: txt_border <= 16'b0000_0000_0000_0000;
			5'b00001: txt_border <= 16'b0000_0000_0000_0000;
			5'b00010: txt_border <= 16'b0000_0000_0000_0000;
			5'b00011: txt_border <= 16'b0000_0000_0000_0000;
			5'b00100: txt_border <= 16'b0000_0000_0000_0001;
			5'b00101: txt_border <= 16'b0000_0000_0000_0000;
			5'b00110: txt_border <= 16'b0000_0000_0000_0001;
			5'b00111: txt_border <= 16'b0000_0000_0000_0001;
			5'b01000: txt_border <= 16'b1000_0000_0000_0000;
			5'b01001: txt_border <= 16'b1000_0000_0000_0000;
			5'b01010: txt_border <= 16'b1000_0000_0000_0000;
			5'b01011: txt_border <= 16'b0000_0000_0000_0000;
			5'b01100: txt_border <= 16'b1000_0000_0000_0001;
			5'b01101: txt_border <= 16'b1000_0000_0000_0000;
			5'b01110: txt_border <= 16'b1000_0000_0000_0001;
			5'b01111: txt_border <= 16'b0000_0000_0000_0001;
			default: txt_border <= 16'b1111_1111_1111_1111;
		endcase
	end else begin
		txt_border <= 16'b0000_0000_0000_0000;
	end
end else begin
	txt_enable <= FALSE;
	gfx_enable <= FALSE;
end
endmodule

`timescale 1ns / 1ps
