  assign wire7 = (-$unsigned((|($unsigned(wire0) * (wire1 == wire4)))));
  assign wire8 = $unsigned(wire1[(1'h0):(1'h0)]);
  assign wire9 = wire8;
  assign wire10 = ((|$signed(wire9[(2'h2):(2'h2)])) >> $signed($signed(({wire0,
                      wire8} > (wire8 ? wire5 : wire7)))));
endmodule

