// Revision 1.3  2008/06/18 18:45:07  Nathan
// Improved reset slightly.  Cleanup.
//
//
// Revision 1.2 2008/05/14 13:13:24 Nathan
// Rewrote TAP FSM in canonical form, for readability.  Switched
// from one-hot to binary encoding.  Made reset signal active-
// low, per JTAG spec.  Removed FF chain for 5 TMS reset - reset
// done in Test Logic Reset mode.  Added test_logic_reset_o and
// run_test_idle_o signals.  Removed double registers from IR data
// path.  Unified the registers at the output of each data register
// to a single shared FF.
//


// Updated by Mohamed Shalan to remove unnecessary functions

//`include "tap_defines.v"
// Define IDCODE Value
// ARM IDCODE for Cortex M0 is 0BA01477
`define IDCODE_VALUE  32'h1_0001_00_1
// 0001                 version
// 0000_0000_0000_0001  part number (1)
// 0000_0000_000        manufacturer id (0)
// 1                    required by standard

// Length of the Instruction register
`define	IR_LENGTH	4

// Supported Instructions
`define EXTEST          4'b0000
`define SAMPLE_PRELOAD  4'b0001
`define IDCODE          4'b0010
`define DEBUG           4'b1000
`define MBIST           4'b1001
`define BYPASS          4'b1111

// Top module
module jtag_tap(
        // JTAG pads
        input      tms_pad_i, // JTAG test mode select pad
        input      tck_pad_i, // JTAG test clock pad
        input      trstn_pad_i, // JTAG test reset pad
        input      tdi_pad_i, // JTAG test data input pad
        output reg tdo_pad_o, // JTAG test data output pad
        output reg tdo_padoe_o// Output enable for JTAG test data output pad
    );

    // Wires which depend on the state of the TAP FSM
    reg     test_logic_reset;
    reg     run_test_idle;
    reg     select_dr_scan;
    reg     capture_dr;
    reg     shift_dr;
    reg     exit1_dr;
    reg     pause_dr;
    reg     exit2_dr;
    reg     update_dr;
    reg     select_ir_scan;
    reg     capture_ir;
    reg     shift_ir;
    reg     exit1_ir;
    reg     pause_ir;
    reg     exit2_ir;
    reg     update_ir;

    // Wires which depend on the current value in the IR
    reg     idcode_select;
    reg     bypass_select;

    assign tdi_o = tdi_pad_i;

    // Definition of machine state values.  We could one-hot encode this, and use 16
    // registers, but this uses binary encoding for the minimum of 4 DFF's instead.
`define STATE_test_logic_reset 4'hF
`define STATE_run_test_idle    4'hC
`define STATE_select_dr_scan   4'h7
`define STATE_capture_dr       4'h6
`define STATE_shift_dr         4'h2
`define STATE_exit1_dr         4'h1
`define STATE_pause_dr         4'h3
`define STATE_exit2_dr         4'h0
`define STATE_update_dr        4'h5
`define STATE_select_ir_scan   4'h4
`define STATE_capture_ir       4'hE
`define STATE_shift_ir         4'hA
`define STATE_exit1_ir         4'h9
`define STATE_pause_ir         4'hB
`define STATE_exit2_ir         4'h8
`define STATE_update_ir        4'hD

    reg [3:0] TAP_state = `STATE_test_logic_reset;  // current state of the TAP controller
    reg [3:0] next_TAP_state;  // state TAP will take at next rising TCK, combinational signal

    // sequential part of the FSM
    always @ (posedge tck_pad_i or negedge trstn_pad_i) begin
        if(trstn_pad_i == 0)
            TAP_state = `STATE_test_logic_reset;
        else
            TAP_state = next_TAP_state;
    end


    // Determination of next state; purely combinatorial
    always @ (TAP_state or tms_pad_i) begin
        case(TAP_state)
            `STATE_test_logic_reset: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_test_logic_reset;
                else
                    next_TAP_state = `STATE_run_test_idle;
            end
            `STATE_run_test_idle: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_select_dr_scan;
                else
                    next_TAP_state = `STATE_run_test_idle;
            end
            `STATE_select_dr_scan: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_select_ir_scan;
                else
                    next_TAP_state = `STATE_capture_dr;
            end
            `STATE_capture_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit1_dr;
                else
                    next_TAP_state = `STATE_shift_dr;
            end
            `STATE_shift_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit1_dr;
                else
                    next_TAP_state = `STATE_shift_dr;
            end
            `STATE_exit1_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_update_dr;
                else
                    next_TAP_state = `STATE_pause_dr;
            end
            `STATE_pause_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit2_dr;
                else
                    next_TAP_state = `STATE_pause_dr;
            end
            `STATE_exit2_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_update_dr;
                else
                    next_TAP_state = `STATE_shift_dr;
            end
            `STATE_update_dr: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_select_dr_scan;
                else
                    next_TAP_state = `STATE_run_test_idle;
            end
            `STATE_select_ir_scan: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_test_logic_reset;
                else
                    next_TAP_state = `STATE_capture_ir;
            end
            `STATE_capture_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit1_ir;
                else
                    next_TAP_state = `STATE_shift_ir;
            end
            `STATE_shift_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit1_ir;
                else
                    next_TAP_state = `STATE_shift_ir;
            end
            `STATE_exit1_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_update_ir;
                else
                    next_TAP_state = `STATE_pause_ir;
            end
            `STATE_pause_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_exit2_ir;
                else
                    next_TAP_state = `STATE_pause_ir;
            end
            `STATE_exit2_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_update_ir;
                else
                    next_TAP_state = `STATE_shift_ir;
            end
            `STATE_update_ir: begin
                if(tms_pad_i)
                    next_TAP_state = `STATE_select_dr_scan;
                else
                    next_TAP_state = `STATE_run_test_idle;
            end
            default:
                next_TAP_state = `STATE_test_logic_reset;  // can't actually happen
        endcase
    end


    // Outputs of state machine, pure combinatorial
    always @ (TAP_state) begin
        // Default everything to 0, keeps the case statement simple
        test_logic_reset = 1'b0;
        run_test_idle = 1'b0;
        select_dr_scan = 1'b0;
        capture_dr = 1'b0;
        shift_dr = 1'b0;
        exit1_dr = 1'b0;
        pause_dr = 1'b0;
        exit2_dr = 1'b0;
        update_dr = 1'b0;
        select_ir_scan = 1'b0;
        capture_ir = 1'b0;
        shift_ir = 1'b0;
        exit1_ir = 1'b0;
        pause_ir = 1'b0;
        exit2_ir = 1'b0;
        update_ir = 1'b0;

        case(TAP_state)
            `STATE_test_logic_reset:
                test_logic_reset = 1'b1;
            `STATE_run_test_idle:
                run_test_idle = 1'b1;
            `STATE_select_dr_scan:
                select_dr_scan = 1'b1;
            `STATE_capture_dr:
                capture_dr = 1'b1;
            `STATE_shift_dr:
                shift_dr = 1'b1;
            `STATE_exit1_dr:
                exit1_dr = 1'b1;
            `STATE_pause_dr:
                pause_dr = 1'b1;
            `STATE_exit2_dr:
                exit2_dr = 1'b1;
            `STATE_update_dr:
                update_dr = 1'b1;
            `STATE_select_ir_scan:
                select_ir_scan = 1'b1;
            `STATE_capture_ir:
                capture_ir = 1'b1;
            `STATE_shift_ir:
                shift_ir = 1'b1;
            `STATE_exit1_ir:
                exit1_ir = 1'b1;
            `STATE_pause_ir:
                pause_ir = 1'b1;
            `STATE_exit2_ir:
                exit2_ir = 1'b1;
            `STATE_update_ir:
                update_ir = 1'b1;
            default:
                ;
        endcase
    end

    reg [`IR_LENGTH-1:0]  jtag_ir;          // Instruction register
    reg [`IR_LENGTH-1:0]  latched_jtag_ir; //, latched_jtag_ir_neg;
    wire                  instruction_tdo;

    always @ (posedge tck_pad_i or negedge trstn_pad_i) begin
        if(trstn_pad_i == 0)
            jtag_ir[`IR_LENGTH-1:0] <= #1 `IR_LENGTH'b0;
        else if (test_logic_reset == 1)
            jtag_ir[`IR_LENGTH-1:0] <= #1 `IR_LENGTH'b0;
        else if(capture_ir)
            jtag_ir <= #1 4'b0101;          // This value is fixed for easier fault detection
        else if(shift_ir)
            jtag_ir[`IR_LENGTH-1:0] <= #1 {tdi_pad_i, jtag_ir[`IR_LENGTH-1:1]};
    end

    assign instruction_tdo = jtag_ir[0];  // This is latched on a negative TCK edge after the output MUX

    // Updating jtag_ir (Instruction Register)
    // jtag_ir should be latched on FALLING EDGE of TCK when capture_ir == 1
    always @ (negedge tck_pad_i or negedge trstn_pad_i) begin
        if(trstn_pad_i == 0)
            latched_jtag_ir <=#1 `IDCODE;   // IDCODE selected after reset
        else if (test_logic_reset)
            latched_jtag_ir <=#1 `IDCODE;   // IDCODE selected after reset
        else if(update_ir)
            latched_jtag_ir <=#1 jtag_ir;
    end

    reg [31:0] idcode_reg;
    wire        idcode_tdo;

    always @ (posedge tck_pad_i or negedge trstn_pad_i) begin
        if(trstn_pad_i == 0)
            idcode_reg <=#1 `IDCODE_VALUE;   // IDCODE selected after reset
        else if (test_logic_reset)
            idcode_reg <=#1 `IDCODE_VALUE;   // IDCODE selected after reset
        else if(idcode_select & capture_dr)
            idcode_reg <= #1 `IDCODE_VALUE;
        else if(idcode_select & shift_dr)
            idcode_reg <= #1 {tdi_pad_i, idcode_reg[31:1]};

    end

    assign idcode_tdo = idcode_reg[0];   // This is latched on a negative TCK edge after the output MUX

    wire  bypassed_tdo;
    reg   bypass_reg;  // This is a 1-bit register

    always @ (posedge tck_pad_i or negedge trstn_pad_i) begin
        if (trstn_pad_i == 0)
            bypass_reg <= #1 1'b0;
        else if (test_logic_reset == 1)
            bypass_reg <= #1 1'b0;
        else if (bypass_select & capture_dr)
            bypass_reg<=#1 1'b0;
        else if(bypass_select & shift_dr)
            bypass_reg<=#1 tdi_pad_i;
    end

    assign bypassed_tdo = bypass_reg;   // This is latched on a negative TCK edge after the output MUX

    always @ (latched_jtag_ir) begin
        idcode_select           = 1'b0;
        bypass_select           = 1'b0;

        case(latched_jtag_ir)    /* synthesis parallel_case */
            `IDCODE:
                idcode_select           = 1'b1;    // ID Code
            `BYPASS:
                bypass_select           = 1'b1;    // BYPASS
            default:
                bypass_select           = 1'b1;    // BYPASS
        endcase
    end

    reg tdo_mux_out;  // really just a wire

    always @ (shift_ir or instruction_tdo or latched_jtag_ir or idcode_tdo or bypassed_tdo) begin
        if(shift_ir)
            tdo_mux_out = instruction_tdo;
        else begin
            case(latched_jtag_ir)    // synthesis parallel_case
                `IDCODE:
                    tdo_mux_out = idcode_tdo;       // Reading ID code
                default:
                    tdo_mux_out = bypassed_tdo;     // BYPASS instruction
            endcase
        end
    end


    // TDO changes state at negative edge of TCK
    always @ (negedge tck_pad_i) begin
        tdo_pad_o = tdo_mux_out;
    end


    // Tristate control for tdo_pad_o pin
    always @ (posedge tck_pad_i) begin
        tdo_padoe_o <= #1 shift_ir | shift_dr;
    end

endmodule

`timescale 1ns / 1ps
//Hasan

module autoref_config(
		input clk,
		input rst,

		input set_interval,
		input[27:0] interval_in,
		input set_trfc,
		input[27:0] trfc_in,


		output reg aref_en,
		output reg[27:0] aref_interval,
		output reg[27:0] trfc
    );


	 always@(posedge clk) begin
		if(rst) begin
			aref_en <= 0;
			aref_interval <= 0;
			trfc <= 0;
		end
		else begin
			if(set_interval) begin
				aref_en <= |interval_in;
				aref_interval <= interval_in;
			end //set_interval

			if(set_trfc) begin
				trfc <= trfc_in;
			end
		end
	 end

endmodule

module D_flipflop(
    input clk, reset, d,
    output reg Q
    );

    always @(posedge clk) begin
        if (reset)
            Q <= 1'b0;
        else 
            Q <= d;
    end

endmodule

`include "defines.v"
module d(
    input   wire                rst,
    input   wire[`NIBBLE]       D_rA_i,
    input   wire[`NIBBLE]       D_rB_i,
    output  reg[`NIBBLE]        d_srcA_o,
    output  reg[`NIBBLE]        d_srcB_o
);

    always @ (*) begin
        d_srcA_o    =      D_rA_i;
        d_srcB_o    =      D_rB_i;
    end
endmodule

