module acl_atomics
(
   clock, resetn,

   // arbitration port
   mem_arb_read,
   mem_arb_write,
   mem_arb_burstcount,
   mem_arb_address,
   mem_arb_writedata,
   mem_arb_byteenable,
   mem_arb_waitrequest,
   mem_arb_readdata,
   mem_arb_readdatavalid,
   mem_arb_writeack,

   //  Avalon port
   mem_avm_read,
   mem_avm_write,
   mem_avm_burstcount,
   mem_avm_address,
   mem_avm_writedata,
   mem_avm_byteenable,
   mem_avm_waitrequest,
   mem_avm_readdata,
   mem_avm_readdatavalid,
   mem_avm_writeack
);

/*************
* Parameters *
*************/

// default parameters if host does not specify them
parameter ADDR_WIDTH=27;         // Address width
parameter DATA_WIDTH=256;        // Data width
parameter BURST_WIDTH=6;
parameter BYTEEN_WIDTH=32;
parameter OPERATION_WIDTH=32; // atomic operations are ALL 32-bit
parameter ATOMIC_OP_WIDTH=5;

parameter LATENCY=4096; // assuming we get a response back in this many cycles

/******************
* Local Variables *
******************/

localparam BYTE_SELECT_BITS=$clog2(OPERATION_WIDTH);
localparam LATENCY_BITS=$clog2(LATENCY);
localparam DATA_WIDTH_BITS=$clog2(DATA_WIDTH);

// these should match ACLIntrinsics::ID enum in ACLIntrinsics.h
localparam a_ADD=0;
localparam a_SUB=1;
localparam a_XCHG=2;
localparam a_INC=3;
localparam a_DEC=4;
localparam a_CMPXCHG=5;
localparam a_MIN=6;
localparam a_MAX=7;
localparam a_AND=8;
localparam a_OR=9;
localparam a_XOR=10;

// atomic operation states
localparam a_IDLE=0;
localparam a_STARTED=1;
localparam a_READCOMPLETE=2;
localparam a_WRITEBACK=3;

/********
* Ports *
********/

// Standard global signals
input logic clock;
input logic resetn;

// Arbitration port
input logic mem_arb_read;
input logic mem_arb_write;
input logic [BURST_WIDTH-1:0] mem_arb_burstcount;
input logic [ADDR_WIDTH-1:0] mem_arb_address;
input logic [DATA_WIDTH-1:0] mem_arb_writedata;
input logic [BYTEEN_WIDTH-1:0] mem_arb_byteenable;
output logic mem_arb_waitrequest;
output logic [DATA_WIDTH-1:0] mem_arb_readdata;
output logic mem_arb_readdatavalid;
output logic mem_arb_writeack;

// Avalon port
output mem_avm_read;
output mem_avm_write;
output [BURST_WIDTH-1:0] mem_avm_burstcount;
output [ADDR_WIDTH-1:0] mem_avm_address;
output [DATA_WIDTH-1:0] mem_avm_writedata;
output [BYTEEN_WIDTH-1:0] mem_avm_byteenable;
input mem_avm_waitrequest;
input [DATA_WIDTH-1:0] mem_avm_readdata;
input mem_avm_readdatavalid;
input mem_avm_writeack;

/**********
* Signals *
**********/

wire atomic;
reg [OPERATION_WIDTH-1:0] a_operand0;
reg [OPERATION_WIDTH-1:0] a_operand1;
reg [DATA_WIDTH_BITS-1:0] a_segment_address;
reg [ATOMIC_OP_WIDTH-1:0] a_atomic_op;
reg [BURST_WIDTH-1:0] a_burstcount;

reg [7:0] counter;

wire atomic_read_ready; // high when memory is ready to receive to a read request 
wire atomic_write_ready; // high when memory is ready to receive to a write request

reg [OPERATION_WIDTH-1:0] a_masked_readdata; 
wire [OPERATION_WIDTH-1:0] atomic_add_out;
wire [OPERATION_WIDTH-1:0] atomic_sub_out;
wire [OPERATION_WIDTH-1:0] atomic_xchg_out;
wire [OPERATION_WIDTH-1:0] atomic_inc_out;
wire [OPERATION_WIDTH-1:0] atomic_dec_out;
wire [OPERATION_WIDTH-1:0] atomic_cmpxchg_out;
wire [OPERATION_WIDTH-1:0] atomic_min_out;
wire [OPERATION_WIDTH-1:0] atomic_max_out;
wire [OPERATION_WIDTH-1:0] atomic_and_out;
wire [OPERATION_WIDTH-1:0] atomic_or_out;
wire [OPERATION_WIDTH-1:0] atomic_xor_out;
wire [OPERATION_WIDTH-1:0] atomic_out;

// count responses/requests so we can determine when the atomic load is returned
reg [LATENCY_BITS-1:0] count_requests;
reg [LATENCY_BITS-1:0] count_responses;
reg [LATENCY_BITS-1:0] count_atomic;
wire waiting_atomic_read_response;
wire atomic_read_response;

// keep track of atomic operation state
reg [1:0] atomic_state;
wire atomic_idle;
wire atomic_started;
wire atomic_read_complete;
wire atomic_writeback;

// current atomic operation we are servicing
reg [DATA_WIDTH-1:0] a_writedata;
reg [BYTEEN_WIDTH-1:0] a_byteenable;
reg [ADDR_WIDTH-1:0] a_address;

/************************************
* Read Atomic Inputs, Write Output *
************************************/

always@(posedge clock or negedge resetn)
begin

   if ( !resetn ) begin
     a_writedata = {DATA_WIDTH{1'b0}};
     a_byteenable = {BYTEEN_WIDTH{1'b0}};
     a_address = {ADDR_WIDTH{1'b0}}; 
     a_operand0 = {OPERATION_WIDTH{1'b0}};
     a_operand1 = {OPERATION_WIDTH{1'b0}};
     a_segment_address = {DATA_WIDTH_BITS{1'b0}};
     a_atomic_op = {ATOMIC_OP_WIDTH{1'b0}};
     a_burstcount = {BURST_WIDTH{1'b0}};
   end
   else if( atomic_read_ready ) begin
     a_operand0 = mem_arb_writedata[32:1];
     a_operand1 = mem_arb_writedata[64:33];
     a_atomic_op = mem_arb_writedata[70:65];
     a_segment_address = ( OPERATION_WIDTH * mem_arb_writedata[75:71]);
     a_byteenable = mem_arb_byteenable;
     a_address = mem_arb_address;
     a_burstcount = mem_arb_burstcount;
   end
   else if( atomic_read_complete ) begin
     a_writedata = ( atomic_out << a_segment_address );
   end
   else if( atomic_write_ready ) begin
     a_writedata = {DATA_WIDTH{1'b0}};
   end
end

/*******************************
* Extract inputs from writedata *
********************************/

assign atomic = mem_arb_read & mem_arb_writedata[0:0];

/*********************************
* Arbitration/Avalon connections *
*********************************/

// mask the response
assign mem_arb_readdatavalid = mem_avm_readdatavalid;
assign mem_arb_writeack =  mem_avm_writeack;
assign mem_arb_readdata = mem_avm_readdata;

// dont send a new read/write if servicing an atomic
assign mem_avm_read = ( mem_arb_read & atomic_idle );
assign mem_avm_write = ( mem_arb_write & atomic_idle ) | atomic_writeback;
assign mem_avm_burstcount = atomic_writeback ? a_burstcount : mem_arb_burstcount;
assign mem_avm_address = atomic_writeback ? a_address : mem_arb_address;
assign mem_avm_writedata = atomic_writeback ? a_writedata : mem_arb_writedata;
assign mem_avm_byteenable = atomic_writeback ? a_byteenable : mem_arb_byteenable;

// stall IC 1. stalled by memory
//          2. when servicing an atomic
assign mem_arb_waitrequest = mem_avm_waitrequest | atomic_started | atomic_read_complete | atomic_writeback;

/****************************************
* Keep track of atomic operation states *
****************************************/

always@(posedge clock or negedge resetn)
begin

   if ( !resetn ) begin
     atomic_state = a_IDLE;
   end
   else begin
     if( atomic_idle & atomic_read_ready ) atomic_state = a_STARTED;
     else if( atomic_started & atomic_read_response ) atomic_state = a_READCOMPLETE;
     else if( atomic_read_complete ) atomic_state = a_WRITEBACK;
     else if( atomic_writeback & atomic_write_ready ) atomic_state = a_IDLE;
   end
end

assign atomic_idle = ( atomic_state == a_IDLE );
assign atomic_started = ( atomic_state == a_STARTED );
assign atomic_read_complete = ( atomic_state == a_READCOMPLETE );
assign atomic_writeback = ( atomic_state == a_WRITEBACK );

assign atomic_read_ready = ( atomic & atomic_idle & ~mem_avm_waitrequest );
assign atomic_write_ready = ( atomic_writeback & ~mem_avm_waitrequest );

/****************************
* ALU for atomic operations *
****************************/

// read readdata from memory
always@(posedge clock or negedge resetn)
begin
   if ( !resetn ) begin
     a_masked_readdata = {OPERATION_WIDTH{1'bx}};
   end
   else begin
     a_masked_readdata = mem_avm_readdata[a_segment_address +: OPERATION_WIDTH];
   end
end

assign atomic_add_out = a_masked_readdata + a_operand0;
assign atomic_sub_out = a_masked_readdata - a_operand0;
assign atomic_xchg_out = a_operand0;
assign atomic_inc_out = a_masked_readdata + 1;
assign atomic_dec_out = a_masked_readdata - 1;
assign atomic_cmpxchg_out = ( a_masked_readdata == a_operand0 ) ? a_operand1 : a_masked_readdata;
assign atomic_min_out = ( a_masked_readdata < a_operand0 ) ? a_masked_readdata : a_operand0;
assign atomic_max_out = ( a_masked_readdata > a_operand0 ) ? a_masked_readdata : a_operand0;
assign atomic_and_out = ( a_masked_readdata & a_operand0 );
assign atomic_or_out = ( a_masked_readdata | a_operand0 );
assign atomic_xor_out = ( a_masked_readdata ^ a_operand0 );

// select the output based on atomic operation
assign atomic_out = 
      ( a_atomic_op == a_ADD )     ? atomic_add_out :
      ( a_atomic_op == a_SUB )     ? atomic_sub_out :
      ( a_atomic_op == a_XCHG )    ? atomic_xchg_out :
      ( a_atomic_op == a_INC )     ? atomic_inc_out :
      ( a_atomic_op == a_DEC )     ? atomic_dec_out :
      ( a_atomic_op == a_CMPXCHG ) ? atomic_cmpxchg_out :
      ( a_atomic_op == a_MIN )     ? atomic_min_out :
      ( a_atomic_op == a_MAX )     ? atomic_max_out :
      ( a_atomic_op == a_AND )     ? atomic_and_out :
      ( a_atomic_op == a_OR )      ? atomic_or_out  :
      ( a_atomic_op == a_XOR )     ? atomic_xor_out : {OPERATION_WIDTH{1'bx}};

/***********************
* Find atomic response *
***********************/

always@(posedge clock or negedge resetn)
begin

   // atomic response, clear counters
   if ( !resetn ) begin
     count_requests = { LATENCY_BITS{1'b0} };
     count_responses = { LATENCY_BITS{1'b0} };
     count_atomic = {1'b0};
   end
   else begin

     // new read request
     if( mem_avm_read & ~mem_avm_waitrequest ) begin
       count_requests = count_requests + mem_arb_burstcount;
     end

     // new read response
     if( mem_avm_readdatavalid ) begin
       count_responses = count_responses + 1;
     end

     // new read atomic request
     if( atomic_read_ready ) begin
       count_atomic = count_requests;
     end

   end
end

// we already sent a request for an atomic
// the next response will be for atomic
assign waiting_atomic_read_response = atomic_started & ( count_atomic == count_responses );

assign atomic_read_response = ( waiting_atomic_read_response & mem_avm_readdatavalid );

endmodule

`default_nettype none


/////// NOTE on storing data in memory
// x_bar - [0] low bits
// M_bar - [2] low bits
// m     - not stored in memory as it is always the same
// op_codes:
//    - OPXX = 0 , P = x_bar * x_bar mod m
//    - OPXM = 1, P = x_bar * M_bar mod m
//    - OPX1 = 2, P = x_bar * 1 mod m
//////

module mon_prod (
  clk,
  start,
  op_code,
  n,
  mp_count,
  rd_addr,
  rd_data,
  wr_data,
  wr_addr,
  wr_en,
  stop,
  P,
  );

  parameter ABITS = 8, DBITS = 256;
  parameter BITLEN = 256;
  parameter LOG_BITLEN = 8;
  localparam BETA = 2;
  localparam BETALEN = 1;
  localparam  IDLE = 0;
  localparam  LOADA1 = 1;
  localparam  LOADB1 = 2;
  localparam  CALC = 3;
  localparam  STORE1 = 4;
  localparam  STORE2 = 5;
  localparam  STORE3 = 6;

  localparam OPXX = 2'd0;
  localparam OPXM = 2'd1;
  localparam OPX1 = 2'd2;
  // width of the numbers being multiplied
  // parameter countWidth = 5;{{DBITS-1{1'b0}} rd_data}


  input clk;
  input start;
  input [1:0] op_code;
  input [BITLEN-1:0] n;
  input [LOG_BITLEN:0] mp_count;
  input [DBITS-1:0] rd_data;

  output reg  [ABITS-1:0] rd_addr;
  initial rd_addr = 0;
  output reg  [DBITS-1:0] wr_data;
  output reg  [ABITS-1:0] wr_addr;
  initial wr_addr = 0;
  output reg wr_en;
  initial wr_en = 0;
  output reg stop;
  output reg [BITLEN + BETALEN - 1:0] P;
  initial P = 1025'b0;



  wire [BETALEN-1:0] B_cat;
  assign B_cat = {BETALEN{1'b0}};
  wire [BETALEN-1:0] a0;
  // wire [BETALEN-1:0] m0;
  wire [BETALEN-1:0] mu;

  reg [BITLEN-1:0] A;
  reg [BITLEN-1:0] B;
  reg [2:0]state;
  initial A = {BITLEN{1'b1}};
  initial B = {BITLEN{1'b1}};
  initial state = IDLE;

  // reg [BETALEN-1:0] bt;
  reg [BETALEN-1:0] p0;
  // reg [BETALEN-1:0] qt;
  reg [9:0] count;
  reg [BITLEN + BETALEN - 1:0] P_norm;
  reg [BITLEN + BETALEN - 1:0] P_mid;
  reg [BITLEN + BETALEN - 1:0] P_mid2;


  assign a0 = A[BETALEN-1:0];
  // assign m0 = n[BETALEN-1:0];
  // assign mu = (m0 == 2'd3) ? 2'd1 :
  //             (m0 == 2'd1) ? 2'd3 :
  //             2'd0;
  assign mu = n[BETALEN-1:0];

  wire calc_end;
  assign calc_end = !(| count); // stop = 1 if count is 0


  reg [BETALEN-1:0] small_mult;

  always @(posedge clk) begin
    // $display("mon_prod start: %d", start);
    // $display("start: A: %0d, B: %0d, n: %0d", A, B, n);
    //$display("\nnew clock\n");
    case (state)
      IDLE: begin
        if (start) begin
          // Load the low bits of A, either
          //$display("OPxx?> %0d", op_code === OPXX);
          //$display("OPx1?> %0d", op_code === OPX1);
          rd_addr <= 2; // there is a 2 clock cycle delay for read values, because of commiting of registers
          state <= LOADA1;
          stop <= 0;
          P <= {BITLEN+1 {1'b0}};
          // TODO for real life it should be mp_count-1
          //count <= mp_count; // should be BITLEN if power of 2, otherwise next highest power of 2
          //TODO for fake life it should be mp_count
          count <= mp_count-1; // should be BITLEN if power of 2, otherwise next highest power of 2
          $display("mp_count: %0d", mp_count);
        end
      end

      LOADA1: begin
        A[DBITS-1:0] <= rd_data; // rd data is from addr 0
        B[DBITS-1:0] <= (op_code == OPX1) ? {{DBITS-2{1'b0}}, 1'b1} : rd_data;
        state <= (op_code == OPXM) ? LOADB1: CALC;
        rd_addr <= (op_code == OPXM) ? 2 : 0;
      end

      //LOADA2: begin
        //A[BITLEN-1:DBITS] <= rd_data; // rd data is from addr 1
        //B[BITLEN-1:DBITS] <= (op_code == OPX1) ? {{511{1'b0}}, 1'b1} : rd_data;
        //if (op_code == OPX1) B[DBITS-1:0] <=  {{511{1'b0}}, 1'b1};
        //rd_addr <= (op_code == OPXM) ? 3 : 0;
        //state <= (op_code == OPXM) ? LOADB1: CALC;
        //if(!(op_code == OPXM)) $display("Calc> A: %0d, B: %0d, M: %0d", A, B, M);
      //end

      LOADB1: begin
        B <= {{DBITS-1{1'b0}}, rd_data}; // rd data is from addr 2
        rd_addr <= 0;
        state <= CALC;
        //$display("Calc> A: %0d, B: %0d, M: %0d", A, B, M);
      end

      //LOADB2: begin
        //B <= {rd_data, B[DBITS-1:0]}; // rd data is from addr 3
        //rd_addr <= 0;
        //state <= CALC;
        //$display("Calc> A: %0d, B: %0d, M: %0d", A, B, M);

      //end

      CALC: begin

        //$display("Calc2> A: %0d, B: %0d, M: %0d", A, B, M);

        //$display("big_mult: %0d", A);
        //$display("small_mult: %0d", (B[BETALEN-1:0]));
        P_mid =  (B[BETALEN-1:0]) ? (A + P) :  P;

        small_mult = (mu * (a0 * B[BETALEN-1:0] + P[BETALEN-1:0]));
        //$display("big_mult: %0d", M);
        //$display("small_mult: %0d", small_mult);
        P_mid2 = small_mult ? (P_mid + n) : P_mid;
        B = {B_cat, B[BITLEN-1:BETALEN]};
        P = P_mid2 >> BETALEN;
        count = count - 1;

        //$display("P: %0d", P);

        if (calc_end) begin
          P_norm = P - n;
          P = P_norm[BETALEN + BITLEN - 1] ? P : P_norm;
          //$display("CALC_END: %0d", P);
          state = STORE1;
          wr_data = P[DBITS-1:0];
          wr_en = 1'b1;
          wr_addr = 0;
          //$display("wr_addr: %0d", wr_addr);
        end
        // else it will stay at calc
      end

      //STORE1: begin
        //wr_data <= P[`BITLEN-1:DBITS];
        //wr_en <= 1'b1;
        //wr_addr <= 1;
        //$display("wr_addr: %0d", wr_addr);
        //state <= STORE2;
      //end

      STORE1: begin
        wr_en <= 1'b0;
        state <= IDLE;
        stop <= 1;
        //state <= STORE2;
      end

      //STORE2: begin
        //state <= STORE3;
      //end

      //STORE3: begin
        ////P <= rd_data;
        //state <= IDLE;
        //stop <= 1;
      //end
    endcase
  end
endmodule

`timescale 1ns / 1ps

module TB;

    reg CLK, CLK_SYS, CLK_MUL, Reset;
	 wire CS, WE, CS_P;
	 reg [31:0] Data_BUS_READ, Prog_BUS_READ, writeBack;
    wire [31:0] ADDR, Data_BUS_WRITE, ADDR_Prog; 

    cpu DUT (
        .CLK(CLK),
        .Reset(Reset),
        .Data_BUS_READ(Data_BUS_READ),
        .Prog_BUS_READ(Prog_BUS_READ),
        .ADDR(ADDR),
        .Data_BUS_WRITE(Data_BUS_WRITE),
        .ADDR_Prog(ADDR_Prog),
        .CS(CS),
		  .WE(WE),
		  .CS_P(CS_P)
		     );

    initial begin

		$init_signal_spy("DUT/CLK_SYS","CLK_SYS",1);
		$init_signal_spy("DUT/CLK_MUL","CLK_MUL",1);
		$init_signal_spy("DUT/writeBack","writeBack",1);

		CLK = 0;
		Reset = 1;

		Data_BUS_READ = 32'h0;
		Prog_BUS_READ = 32'h0;

		#10 Reset = 0;


		#100000 $stop;


    always #10 CLK = ~CLK;

endmodule

module network_interface_cdc #(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 32,
    parameter VC_COUNT = 2,      // Virtual channel count
    parameter NODE_ID = 0,       // Unique ID for this node
    parameter SYNC_STAGES = 2    // CDC synchronizer stages
)(
    // Source clock domain (local memory interface)
    input  wire                     src_clk,
    input  wire                     src_rst_n,

    // Destination clock domain (router interface)
    input  wire                     dst_clk,
    input  wire                     dst_rst_n,

    // NoC router interface (dst clock domain)
    output wire [DATA_WIDTH-1:0]    router_in_data,
    output wire                     router_in_valid,
    input  wire                     router_in_ready,
    input  wire [DATA_WIDTH-1:0]    router_out_data,
    input  wire                     router_out_valid,
    output wire                     router_out_ready,

    // Local memory interface (src clock domain)
    input  wire                     mem_write,
    input  wire                     mem_read,
    input  wire [ADDR_WIDTH-1:0]    mem_addr,
    input  wire [DATA_WIDTH-1:0]    mem_wdata,
    output reg  [DATA_WIDTH-1:0]    mem_rdata,
    output reg                      mem_ready,

    // Packetization parameters (src clock domain)
    input  wire [7:0]               dest_id,    // Destination node ID
    input  wire [2:0]               msg_type    // Message type identifier
);

    // Packet format (32-bit total):
    // [31:24] : Destination ID (8 bits)
    // [23:21] : Message Type (3 bits)
    // [20:20] : Read/Write bit (1=write, 0=read)
    // [19:0]  : Address field (20 bits)

    // State machine states
    localparam IDLE = 2'b00;
    localparam SEND = 2'b01;
    localparam WAIT_RESP = 2'b10;
    localparam RECV = 2'b11;

    //-------------------------------------------
    // CDC registers and synchronization signals
    //-------------------------------------------

    // Data crossing from source to destination
    (* keep = "true" *) reg [DATA_WIDTH-1:0] src_to_dst_data;

    // Control signals crossing from source to destination
    (* keep = "true" *) reg src_req;
    (* keep = "true" *) reg src_data_valid;
    (* keep = "true" *) reg src_is_write_op_flag;

    // Data crossing from destination to source 
    (* keep = "true" *) reg [DATA_WIDTH-1:0] dst_to_src_data;

    // Control signals crossing from destination to source
    (* keep = "true" *) reg dst_ack;
    (* keep = "true" *) reg dst_data_valid;

    // Synchronizers for source->destination control signals
    reg [SYNC_STAGES-1:0] src_req_sync_reg;
    reg [SYNC_STAGES-1:0] src_data_valid_sync_reg;
    reg [SYNC_STAGES-1:0] src_is_write_op_sync_reg;
    wire src_req_sync;
    wire src_data_valid_sync;
    wire src_is_write_op_sync;
    reg src_req_prev;

    // Synchronizers for destination->source control signals
    reg [SYNC_STAGES-1:0] dst_ack_sync_reg;
    reg [SYNC_STAGES-1:0] dst_data_valid_sync_reg;
    wire dst_ack_sync;
    wire dst_data_valid_sync;
    reg dst_ack_prev;

    //-------------------------------------------
    // Source clock domain logic (local memory)
    //-------------------------------------------
    reg [1:0] src_state;
    reg src_is_write_op;

    // Synchronize destination signals to source domain
    always @(posedge src_clk or negedge src_rst_n) begin
        if (!src_rst_n) begin
            dst_ack_sync_reg = {SYNC_STAGES{1'b0}};
            dst_data_valid_sync_reg = {SYNC_STAGES{1'b0}};
            dst_ack_prev = 1'b0;
        end else begin
            // Multi-flop synchronizers for control signals
            dst_ack_sync_reg = {dst_ack_sync_reg[SYNC_STAGES-2:0], dst_ack};
            dst_data_valid_sync_reg = {dst_data_valid_sync_reg[SYNC_STAGES-2:0], dst_data_valid};
            dst_ack_prev = dst_ack_sync;
        end
    end

    assign dst_ack_sync = dst_ack_sync_reg[SYNC_STAGES-1];
    assign dst_data_valid_sync = dst_data_valid_sync_reg[SYNC_STAGES-1];

    // Source domain state machine
    always @(posedge src_clk or negedge src_rst_n) begin
        if (!src_rst_n) begin
            src_state = IDLE;
            src_to_dst_data = {DATA_WIDTH{1'b0}};
            src_req = 1'b0;
            src_data_valid = 1'b0;
            src_is_write_op_flag = 1'b0;
            mem_rdata = {DATA_WIDTH{1'b0}};
            mem_ready = 1'b0;
            src_is_write_op = 1'b0;
        end else begin
            // Default value (usually cleared each cycle)
            src_data_valid = 1'b0;

            case (src_state)
                IDLE: begin
                    mem_ready = 1'b0;

                    if (mem_write) begin
                        // Assemble write packet
                        src_to_dst_data = (dest_id << 24) | (msg_type << 21) | (1 << 20) | (mem_addr & 'h1FFFFF);
                        src_is_write_op = 1'b1;
                        src_is_write_op_flag = 1'b1;
                        src_req = ~src_req;  // Toggle request bit
                        src_data_valid = 1'b1;
                        src_state = SEND;
                    end else if (mem_read) begin
                        // Assemble read packet
                        src_to_dst_data = (dest_id << 24) | (msg_type << 21) | (0 << 20) | (mem_addr & 'h1FFFFF);
                        src_is_write_op = 1'b0;
                        src_is_write_op_flag = 1'b0;
                        src_req = ~src_req;  // Toggle request bit
                        src_data_valid = 1'b1;
                        src_state = SEND;
                    end
                end

                SEND: begin
                    // Keep data valid until acknowledged
                    src_data_valid = 1'b1;

                    // Wait for destination to acknowledge (ack toggle)
                    if (dst_ack_sync != dst_ack_prev) begin
                        if (src_is_write_op) begin
                            // For write transactions, send data payload next
                            src_to_dst_data = mem_wdata;
                            src_req = ~src_req;  // Toggle request again for data
                            src_data_valid = 1'b1;
                            src_state = WAIT_RESP;
                        end else begin
                            // For read, wait for response
                            src_data_valid = 1'b0;
                            src_state = WAIT_RESP;
                        end
                    end
                end

                WAIT_RESP: begin
                    if (src_is_write_op) begin
                        // Keep data valid until acknowledged
                        src_data_valid = 1'b1;

                        // For write, wait for data acknowledgment (ack toggle)
                        if (dst_ack_sync != dst_ack_prev) begin
                            src_data_valid = 1'b0;
                            mem_ready = 1'b1;
                            src_state = IDLE;
                        end
                    end else begin
                        // For read, wait for data valid flag
                        if (dst_data_valid_sync) begin
                            mem_rdata = dst_to_src_data;
                            mem_ready = 1'b1;
                            src_state = RECV;
                        end
                    end
                end

                RECV: begin
                    // Complete the read transaction
                    mem_ready = 1'b0;
                    src_state = IDLE;
                end
            endcase
        end
    end

    //-------------------------------------------
    // Destination clock domain logic (router)
    //-------------------------------------------
    reg [1:0] dst_state;
    reg [DATA_WIDTH-1:0] dst_data_reg;
    reg dst_valid;
    reg dst_is_write_op;

    // Synchronize source control signals to destination domain
    always @(posedge dst_clk or negedge dst_rst_n) begin
        if (!dst_rst_n) begin
            src_req_sync_reg = {SYNC_STAGES{1'b0}};
            src_data_valid_sync_reg = {SYNC_STAGES{1'b0}};
            src_is_write_op_sync_reg = {SYNC_STAGES{1'b0}};
            src_req_prev = 1'b0;
        end else begin
            src_req_sync_reg = {src_req_sync_reg[SYNC_STAGES-2:0], src_req};
            src_data_valid_sync_reg = {src_data_valid_sync_reg[SYNC_STAGES-2:0], src_data_valid};
            src_is_write_op_sync_reg = {src_is_write_op_sync_reg[SYNC_STAGES-2:0], src_is_write_op_flag};
            src_req_prev = src_req_sync;
        end
    end

    assign src_req_sync = src_req_sync_reg[SYNC_STAGES-1];
    assign src_data_valid_sync = src_data_valid_sync_reg[SYNC_STAGES-1];
    assign src_is_write_op_sync = src_is_write_op_sync_reg[SYNC_STAGES-1];

    // Destination domain state machine
    always @(posedge dst_clk or negedge dst_rst_n) begin
        if (!dst_rst_n) begin
            dst_state = IDLE;
            dst_data_reg = {DATA_WIDTH{1'b0}};
            dst_valid = 1'b0;
            dst_is_write_op = 1'b0;
            dst_ack = 1'b0;
            dst_to_src_data = {DATA_WIDTH{1'b0}};
            dst_data_valid = 1'b0;
        end else begin
            // Default values
            dst_valid = 1'b0;
            dst_data_valid = 1'b0;

            case (dst_state)
                IDLE: begin
                    // Detect change in request signal (new transaction)
                    if ((src_req_sync != src_req_prev) && src_data_valid_sync) begin
                        // Capture the data from source domain
                        dst_data_reg = src_to_dst_data;

                        // Capture operation type
                        dst_is_write_op = src_is_write_op_sync;

                        // Acknowledge by toggling ack
                        dst_ack = ~dst_ack;

                        // Set valid to send to router
                        dst_valid = 1'b1;
                        dst_state = SEND;
                    end
                end

                SEND: begin
                    // Keep valid high until router accepts
                    dst_valid = 1'b1;

                    if (router_in_ready && dst_valid) begin
                        if (dst_is_write_op) begin
                            // For write, wait for data packet
                            dst_valid = 1'b0;
                            dst_state = WAIT_RESP;
                        end else begin
                            // For read, wait for router response
                            dst_valid = 1'b0;
                            dst_state = WAIT_RESP;
                        end
                    end
                end

                WAIT_RESP: begin
                    if (dst_is_write_op) begin
                        // Detect change in request signal (data packet arrived)
                        if ((src_req_sync != src_req_prev) && src_data_valid_sync) begin
                            // Capture the data payload
                            dst_data_reg = src_to_dst_data;
                            dst_valid = 1'b1;

                            // Acknowledge by toggling ack
                            dst_ack = ~dst_ack;
                            dst_state = RECV;
                        end
                    end else begin
                        // For read transactions, wait for router response
                        if (router_out_valid) begin
                            // Capture the data from router
                            dst_to_src_data = router_out_data;

                            // Signal that data is valid
                            dst_data_valid = 1'b1;
                            dst_state = RECV;
                        end
                    end
                end

                RECV: begin
                    // For write, send data to router
                    if (dst_is_write_op) begin
                        // Keep trying to send until router accepts
                        dst_valid = 1'b1;

                        if (router_in_ready && dst_valid) begin
                            dst_state = IDLE;
                        end
                    end else begin
                        // For read transactions, keep data valid signal high
                        // to ensure it's detected in source domain
                        dst_data_valid = 1'b1;

                        // Move back to IDLE after a few cycles
                        // The testbench will see the data before this happens
                        if (src_data_valid_sync == 1'b0) begin
                            dst_state = IDLE;
                        end
                    end
                end
            endcase
        end
    end

    // Connect to router interface
    assign router_in_data = dst_data_reg;
    assign router_in_valid = dst_valid;
    assign router_out_ready = (dst_state == WAIT_RESP) || (dst_state == RECV);

endmodule

/* 

 * 
 * --------------------
 */
//-------------------------Timescale----------------------------//
`timescale 1 ns / 1 ps 
//-----------------------Module rst_n---------------------------//
module rst_n(
	input clk_25m,
	output rst_n
);

reg [5:0]rst_cnt;
always@()
	if(rst_cnt == 4'd50)
		begin 
			rst_cnt <= 4'd50;
		end 
	else 
		rst_cnt <= rst_cnt + 1'd1;

assign rst_n = (rst_cnt == 4'd50) ? 1'd1 : 1'd0;

endmodule

module Core (
	clk,
	rst,
	en,
	IN_instrRaw,
	OUT_MEM_writeAddr,
	OUT_MEM_writeData,
	OUT_MEM_writeEnable,
	OUT_MEM_writeMask,
	OUT_MEM_readEnable,
	OUT_MEM_readAddr,
	IN_MEM_readData,
	OUT_instrAddr,
	OUT_instrReadEnable,
	OUT_halt,
	OUT_SPI_cs,
	OUT_SPI_clk,
	OUT_SPI_mosi,
	IN_SPI_miso,
	OUT_MC_ce,
	OUT_MC_we,
	OUT_MC_cacheID,
	OUT_MC_sramAddr,
	OUT_MC_extAddr,
	IN_MC_progress,
	IN_MC_busy
);
	parameter NUM_UOPS = 2;
	parameter NUM_WBS = 4;
	input wire clk;
	input wire rst;
	input wire en;
	input wire [127:0] IN_instrRaw;
	output wire [29:0] OUT_MEM_writeAddr;
	output wire [31:0] OUT_MEM_writeData;
	output wire OUT_MEM_writeEnable;
	output wire [3:0] OUT_MEM_writeMask;
	output wire OUT_MEM_readEnable;
	output wire [29:0] OUT_MEM_readAddr;
	input wire [31:0] IN_MEM_readData;
	output wire [27:0] OUT_instrAddr;
	output wire OUT_instrReadEnable;
	output wire OUT_halt;
	output wire OUT_SPI_cs;
	output wire OUT_SPI_clk;
	output wire OUT_SPI_mosi;
	input wire IN_SPI_miso;
	output reg OUT_MC_ce;
	output reg OUT_MC_we;
	output reg [0:0] OUT_MC_cacheID;
	output reg [9:0] OUT_MC_sramAddr;
	output reg [29:0] OUT_MC_extAddr;
	input wire [9:0] IN_MC_progress;
	input wire IN_MC_busy;
	wire [41:0] CC_MC_if;
	wire [41:0] PC_MC_if;
	always @(*)
		if (PC_MC_if[41]) begin
			OUT_MC_ce = PC_MC_if[41];
			OUT_MC_we = PC_MC_if[40];
			OUT_MC_sramAddr = PC_MC_if[39-:10];
			OUT_MC_extAddr = PC_MC_if[29-:30];
			OUT_MC_cacheID = 1;
		end
		else begin
			OUT_MC_ce = CC_MC_if[41];
			OUT_MC_we = CC_MC_if[40];
			OUT_MC_sramAddr = CC_MC_if[39-:10];
			OUT_MC_extAddr = CC_MC_if[29-:30];
			OUT_MC_cacheID = 0;
		end
	integer i;
	wire [(NUM_WBS * 88) - 1:0] wbUOp;
	wire [NUM_WBS - 1:0] wbHasResult;
	wire wbHasResult_int [NUM_WBS - 1:0];
	assign wbHasResult[0] = wbUOp[0] && (wbUOp[48-:5] != 0);
	assign wbHasResult[1] = wbUOp[88] && (wbUOp[136-:5] != 0);
	assign wbHasResult[2] = wbUOp[176] && (wbUOp[224-:5] != 0);
	assign wbHasResult[3] = wbUOp[264] && (wbUOp[312-:5] != 0);
	assign wbHasResult_int[0] = wbUOp[0] && (wbUOp[48-:5] != 0);
	assign wbHasResult_int[1] = wbUOp[88] && (wbUOp[136-:5] != 0);
	assign wbHasResult_int[2] = wbUOp[176] && (wbUOp[224-:5] != 0);
	assign wbHasResult_int[3] = wbUOp[264] && (wbUOp[312-:5] != 0);
	wire [91:0] comUOps;
	wire comValid [3:0];
	wire frontendEn;
	wire ifetchEn;
	reg [2:0] stateValid;
	assign OUT_instrReadEnable = !(ifetchEn && stateValid[0]);
	reg [127:0] instrRawBackup;
	reg useInstrRawBackup;
	wire [127:0] instrRaw = (useInstrRawBackup ? instrRawBackup : IN_instrRaw);
	always @(posedge clk)
		if (rst)
			useInstrRawBackup <= 0;
		else if (!(ifetchEn && stateValid[0])) begin
			instrRawBackup <= instrRaw;
			useInstrRawBackup <= 1;
		end
		else
			useInstrRawBackup <= 0;
	wire [303:0] branchProvs;
	wire [75:0] branch;
	wire mispredFlush;
	wire [6:0] RN_nextSqN;
	wire [6:0] ROB_curSqN;
	BranchSelector bsel(
		.clk(clk),
		.rst(rst),
		.IN_branches(branchProvs),
		.OUT_branch(branch),
		.IN_ROB_curSqN(ROB_curSqN),
		.IN_RN_nextSqN(RN_nextSqN),
		.IN_mispredFlush(mispredFlush)
	);
	wire [31:0] PC_pc;
	wire BP_branchTaken;
	wire BP_isJump;
	wire [31:0] BP_branchSrc;
	wire [31:0] BP_branchDst;
	wire [15:0] BP_branchHistory;
	wire [8:0] BP_info;
	wire BP_multipleBranches;
	wire BP_branchFound;
	wire BP_branchCompr;
	wire [431:0] IF_instrs;
	wire [24:0] PC_readAddress;
	wire [294:0] PC_readData;
	wire PC_stall;
	wire DEC_branch;
	wire [30:0] DEC_branchDst;
	wire [4:0] DEC_branchFetchID;
	wire ROB_clearICache;
	wire [4:0] ROB_curFetchID;
	ProgramCounter progCnt(
		.clk(clk),
		.en0(stateValid[0] && ifetchEn),
		.en1(stateValid[1] && ifetchEn),
		.rst(rst),
		.IN_pc((branch[0] ? branch[75-:32] : {DEC_branchDst, 1'b0})),
		.IN_write(branch[0] || DEC_branch),
		.IN_branchTaken(branch[0]),
		.IN_fetchID((branch[0] ? branch[21-:5] : DEC_branchFetchID)),
		.IN_instr(instrRaw),
		.IN_clearICache(ROB_clearICache),
		.IN_BP_branchTaken(BP_branchTaken),
		.IN_BP_isJump(BP_isJump),
		.IN_BP_branchSrc(BP_branchSrc),
		.IN_BP_branchDst(BP_branchDst),
		.IN_BP_history(BP_branchHistory),
		.IN_BP_info(BP_info),
		.IN_BP_multipleBranches(BP_multipleBranches),
		.IN_BP_branchFound(BP_branchFound),
		.IN_BP_branchCompr(BP_branchCompr),
		.IN_pcReadAddr(PC_readAddress),
		.OUT_pcReadData(PC_readData),
		.IN_ROB_curFetchID(ROB_curFetchID),
		.OUT_pcRaw(PC_pc),
		.OUT_instrAddr(OUT_instrAddr),
		.OUT_instrs(IF_instrs),
		.OUT_stall(PC_stall),
		.OUT_MC_if(PC_MC_if),
		.IN_MC_cacheID(OUT_MC_cacheID),
		.IN_MC_progress(IN_MC_progress),
		.IN_MC_busy(IN_MC_busy || CC_MC_if[41])
	);
	wire [133:0] BP_btUpdates;
	wire [58:0] ROB_bpUpdate;
	BranchPredictor bp(
		.clk(clk),
		.rst(rst),
		.IN_clearICache(ROB_clearICache),
		.IN_mispredFlush(mispredFlush),
		.IN_branch(branch),
		.IN_pcValid(stateValid[0] && ifetchEn),
		.IN_pc(PC_pc),
		.OUT_branchTaken(BP_branchTaken),
		.OUT_isJump(BP_isJump),
		.OUT_branchSrc(BP_branchSrc),
		.OUT_branchDst(BP_branchDst),
		.OUT_branchHistory(BP_branchHistory),
		.OUT_branchInfo(BP_info),
		.OUT_multipleBranches(BP_multipleBranches),
		.OUT_branchFound(BP_branchFound),
		.OUT_branchCompr(BP_branchCompr),
		.IN_btUpdates(BP_btUpdates),
		.IN_bpUpdate(ROB_bpUpdate)
	);
	wire [125:0] IBP_updates;
	wire [30:0] IBP_predDst;
	IndirectBranchPredictor ibp(
		.clk(clk),
		.rst(rst),
		.IN_clearICache(ROB_clearICache),
		.IN_ibUpdates(IBP_updates),
		.OUT_predDst(IBP_predDst)
	);
	always @(posedge clk)
		if (rst)
			stateValid <= 3'b000;
		else if (branch[0] || DEC_branch)
			stateValid <= 3'b000;
		else if (ifetchEn)
			stateValid <= {stateValid[1:0], 1'b1};
	wire PD_full;
	wire [279:0] PD_instrs;
	wire RN_stall;
	wire FUSE_full = !frontendEn || RN_stall;
	PreDecode preDec(
		.clk(clk),
		.rst(rst),
		.ifetchValid(stateValid[2] && ifetchEn),
		.outEn(!FUSE_full),
		.OUT_full(PD_full),
		.mispred(branch[0] || DEC_branch),
		.IN_instrs(IF_instrs),
		.OUT_instrs(PD_instrs)
	);
	wire ROB_disableIFetch;
	assign ifetchEn = (!PD_full && !PC_stall) && !ROB_disableIFetch;
	wire [271:0] DE_uop;
	wire [7:0] CR_mode;
	InstrDecoder idec(
		.clk(clk),
		.rst(rst),
		.IN_invalidate(branch[0]),
		.en(!FUSE_full),
		.IN_instrs(PD_instrs),
		.IN_indirBranchTarget(IBP_predDst),
		.IN_enCustom(!CR_mode[3'd7]),
		.OUT_decBranch(DEC_branch),
		.OUT_decBranchDst(DEC_branchDst),
		.OUT_decBranchFetchID(DEC_branchFetchID),
		.OUT_uop(DE_uop)
	);
	wire [403:0] RN_uop;
	wire [3:0] RN_uopValid;
	wire [6:0] RN_nextLoadSqN;
	wire [6:0] RN_nextStoreSqN;
	wire [3:0] RN_uopOrdering;
	Rename rn(
		.clk(clk),
		.en(!branch[0] && !mispredFlush),
		.frontEn(frontendEn),
		.rst(rst),
		.OUT_stall(RN_stall),
		.IN_uop(DE_uop),
		.IN_comUOp(comUOps),
		.IN_wbHasResult(wbHasResult),
		.IN_wbUOp(wbUOp),
		.IN_branchTaken(branch[0]),
		.IN_branchFlush(branch[22]),
		.IN_branchSqN(branch[43-:7]),
		.IN_branchLoadSqN(branch[29-:7]),
		.IN_branchStoreSqN(branch[36-:7]),
		.IN_mispredFlush(mispredFlush),
		.OUT_uopValid(RN_uopValid),
		.OUT_uop(RN_uop),
		.OUT_uopOrdering(RN_uopOrdering),
		.OUT_nextSqN(RN_nextSqN),
		.OUT_nextLoadSqN(RN_nextLoadSqN),
		.OUT_nextStoreSqN(RN_nextStoreSqN)
	);
	wire [3:0] RV_uopValid;
	wire [403:0] RV_uop;
	wire [3:0] stall;
	assign stall[0] = 0;
	assign stall[1] = 0;
	wire IQ0_full;
	wire DIV_busy;
	wire [795:0] LD_uop;
	wire [31:0] enabledXUs;
	wire DIV_doNotIssue = (DIV_busy || (LD_uop[0] && enabledXUs[4])) || (RV_uopValid[0] && (RV_uop[4-:4] == 4'd4));
	wire [6:0] LB_maxLoadSqN;
	wire [6:0] LSU_loadFwdTag;
	wire LSU_loadFwdValid;
	wire [6:0] SQ_maxStoreSqN;
	IssueQueue #(
		.SIZE(8),
		.NUM_UOPS(4),
		.RESULT_BUS_COUNT(4),
		.IMM_BITS(32),
		.FU0(4'd0),
		.FU1(4'd4),
		.FU2(4'd5),
		.FU3(4'd5),
		.FU0_SPLIT(1),
		.FU0_ORDER(0),
		.FU1_DLY(33)
	) iq0(
		.clk(clk),
		.rst(rst),
		.frontEn(((frontendEn && !branch[0]) && !mispredFlush) && !RN_stall),
		.IN_stall(stall[0]),
		.IN_doNotIssueFU1(DIV_doNotIssue),
		.IN_doNotIssueFU2(1'b0),
		.IN_uopValid(RN_uopValid),
		.IN_uop(RN_uop),
		.IN_uopOrdering(RN_uopOrdering),
		.IN_resultValid(wbHasResult),
		.IN_resultUOp(wbUOp),
		.IN_loadForwardValid(LSU_loadFwdValid),
		.IN_loadForwardTag(LSU_loadFwdTag),
		.IN_branch(branch),
		.IN_issueValid(RV_uopValid),
		.IN_issueUOps(RV_uop),
		.IN_maxStoreSqN(SQ_maxStoreSqN),
		.IN_maxLoadSqN(LB_maxLoadSqN),
		.OUT_valid(RV_uopValid[0]),
		.OUT_uop(RV_uop[0+:101]),
		.OUT_full(IQ0_full)
	);
	wire IQ1_full;
	wire FDIV_busy;
	wire FDIV_doNotIssue = (FDIV_busy || (LD_uop[199] && enabledXUs[14])) || (RV_uopValid[1] && (RV_uop[105-:4] == 4'd6));
	wire MUL_doNotIssue = 0;
	IssueQueue #(
		.SIZE(8),
		.NUM_UOPS(4),
		.RESULT_BUS_COUNT(4),
		.IMM_BITS(32),
		.FU0(4'd0),
		.FU1(4'd3),
		.FU2(4'd6),
		.FU3(4'd7),
		.FU0_SPLIT(1),
		.FU0_ORDER(1),
		.FU1_DLY(5)
	) iq1(
		.clk(clk),
		.rst(rst),
		.frontEn(((frontendEn && !branch[0]) && !mispredFlush) && !RN_stall),
		.IN_stall(stall[1]),
		.IN_doNotIssueFU1(MUL_doNotIssue),
		.IN_doNotIssueFU2(FDIV_doNotIssue),
