		begin
			// MEALY FSMs - Blocking Operations //
			next_state = state;

			e_q_PLUS = 1'b0;
			e_x_MINUS = 1'b0;
			e_x_MINUSa = 1'b0;
			e_x_PLUSa = 1'b0;
			e_y_MINUSa = 1'b0;
			e_y_PLUS = 1'b0;
			e_q_MINUS = 1'b0;

