				12'bxxxxxxxxx1xx: // p17_1HOT_ENCODING: //
					begin
						if (e_q_MINUS_TB_sync)
							begin
								e_q_MINUS = 1'b1;
								// next_state = p18_1HOT_CASEX_ENCODING; //
