module ram #(
    parameter RAM_FILENAME        = "../../../roms/ram.hex"
) (
    input clk,              // clock signal
    input [14:0] address,   // address bus
    input w_en,             // active high write enable strobe
    input [7:0] din,        // 8-bit data bus (input)
    output reg [7:0] dout   // 8-bit data bus (output)
);

    reg [7:0] ram_data[0:32767];

    //initial
    //    $readmemh(RAM_FILENAME, ram_data, 0, 8191);

    always @(posedge clk)
    begin
        dout <= ram_data[address];
        if (w_en) ram_data[address] <= din;
    end

endmodule

module usbhost(
	//interface
	input wire rst,
	input wire iclk,		//interface clk
	input wire [7:0]wdata,	//interface commands and data
	input wire wr,			//write
	output wire [1:0]wr_level,
	output wire [7:0]rdata,	//result data
	input wire rd,			//read
	output wire rdata_ready,

	//core
	input wire cclk, //core clock, 12MHz

	input  wire i_dp,
	input  wire i_dm,
	output wire o_dp,
	output wire o_dm,
	output wire o_oe,
	output wire [7:0]leds
);

//controller serial bytes protocol 
localparam CMD_GET_LINES = 4'h1; //controller must once poll and return one byte state of USB lines
localparam CMD_BUS_CTRL  = 4'h2; //controller must set bus to reset/normal and/or or enabled/disabled state
									//reset state - dm/dm in zero
									//enabled state when no reset and 1ms periodic SE0 impulses go
localparam CMD_WAIT_EOF  = 4'h3; //controller just waits EOF/SE0 condition
									//any bus operation should start from this, so any read/write start //at begin of frame
localparam CMD_SEND_PKT  = 4'h4; //new packed will be sent to bus. high 4 bits of cmd byte mean data length
localparam CMD_READ_PKT  = 4'h5;
localparam CMD_AUTO_ACK  = 4'h6;

//controller state machine states
localparam STATE_IDLE = 0;
localparam STATE_READ_CMD = 1;
localparam STATE_GOT_CMD = 2;
localparam STATE_READ_LINES = 3;
localparam STATE_BUS_CONTROL = 4;
localparam STATE_WAIT_EOF = 5;
localparam STATE_WAIT_NO_EOF = 6;
localparam STATE_WAIT_BIT0 = 7;
localparam STATE_WAIT_BIT1 = 8;
localparam STATE_FETCH_SEND_BYTE = 9;
localparam STATE_CATCH_SEND_BYTE = 10;
localparam STATE_FETCH_SEND_BYTE1 = 11;
localparam STATE_CATCH_SEND_BYTE1 = 12;
localparam STATE_SENDING = 13;
localparam STATE_WAIT_ACK = 14;
localparam STATE_READ_DATA = 15;
localparam STATE_READ_DATA_ALL = 16;
localparam STATE_COPY_TMP_PKT = 17;
localparam STATE_COPY_TMP_PKT2 = 18;
localparam STATE_SEND_ACK_WAIT_BIT0 = 19;
localparam STATE_SEND_ACK_WAIT_BIT1 = 20;
localparam STATE_SEND_ACK_80 = 21;
localparam STATE_SEND_ACK_D2 = 22;

reg [7:0]state = 0;

//make low speed bit impulse
reg [2:0]cnt;
reg bit_impulse;
always @()
begin
	if(rst)
	begin
		cnt <= 0;
		bit_impulse <= 0;
	end
	else
	begin
		cnt <= cnt + 1;
		bit_impulse <= (cnt==7);
	end
end

//make frame EOF impulse
reg eof;
reg [10:0]bit_time;
always @(posedge cclk or posedge rst)
begin
	if(rst)
	begin
		bit_time <= 0;
		eof <= 1'b0;
	end
	else
	begin
		if(bit_impulse)
		begin
			if(bit_time==1499)
				bit_time <= 0;
			else
				bit_time <= bit_time + 1'b1;
		end

		eof <= (bit_time > 1497 );
	end
end

wire in_empty;
wire [1:0]in_rd_level;
wire [7:0]in_cmd;
reg in_rd=1'b0;

//input data and commands go into FIFO
generic_fifo_dc_gray #( .dw(8), .aw(6) ) fifo_in(
	.rst( ~rst ),
	.rd_clk( cclk ),
	.wr_clk( iclk ),
	.clr( 1'b0 ),
	.din( wdata ),
	.we( wr ),
	.dout( in_cmd ),
	.rd( in_rd ),
	.full(),
	.empty( in_empty ),
	.wr_level( wr_level ),
	.rd_level( in_rd_level )
	);

assign leds = in_cmd;

//result data go to output FIFO
wire [7:0]out_data;
wire out_data_wr;
wire empty;
assign rdata_ready = ~empty;

generic_fifo_dc_gray #( .dw(8), .aw(4) ) fifo_out(
	.rst( ~rst ),
	.rd_clk( iclk ),
	.wr_clk( cclk ),
	.clr( 1'b0 ),
	.din( out_data ),
	.we(  out_data_wr ),
	.dout( rdata ),
	.rd( rd ),
	.full(),
	.empty( empty ),
	.wr_level(  ),
	.rd_level( )
	);

wire [7:0]usb_rdata;
wire usb_rdata_ready;
wire eop_r;
wire enable_recv;

//Need temporary fifo to store USB packet received from USB bus.
//When USB packet received, then we know actual packet length and then
//we can copy temporary data into output fifo, but first in protocol go packet length encoded with command
wire [7:0]tmp_fifo_data;
wire tmp_fifo_rd; assign tmp_fifo_rd = (~tmp_fifo_empty) & (state==STATE_COPY_TMP_PKT);
wire tmp_fifo_empty;
generic_fifo_dc_gray #( .dw(8), .aw(4) ) fifo_out_tmp(
	.rst( ~rst ),
	.rd_clk( cclk ),
	.wr_clk( cclk ),
	.clr( state==STATE_READ_DATA ), //reset tmp fifo at begin of any recv packet
	.din( usb_rdata ),
	.we(  usb_rdata_ready ),
	.dout( tmp_fifo_data ),
	.rd( tmp_fifo_rd ),
	.full(),
	.empty( tmp_fifo_empty ),
	.wr_level(  ),
	.rd_level( )
	);

assign out_data = 
		(state==STATE_READ_LINES) ? { 2'b00, i_dp, i_dm, CMD_GET_LINES }: 
		( (state==STATE_READ_DATA_ALL) & got_recv_pkt_length) ? { usb_rbyte_cnt, CMD_READ_PKT }: 
		tmp_fifo_data;

assign out_data_wr = 
		(state==STATE_READ_LINES) | 
		((state==STATE_READ_DATA_ALL) & got_recv_pkt_length) | 
		(state==STATE_COPY_TMP_PKT & (~tmp_fifo_empty) );

assign enable_recv = (state==STATE_READ_DATA) | (state==STATE_READ_DATA_ALL);

always @*
	in_rd = (state==STATE_READ_CMD) || (state==STATE_FETCH_SEND_BYTE) || (state==STATE_FETCH_SEND_BYTE1);

reg cmd_ready=1'b0;
always @( posedge cclk )
	cmd_ready <= in_rd;

reg [7:0]in_cmd_;
always @( posedge cclk )
	if( cmd_ready && state==STATE_GOT_CMD )
		in_cmd_ <= in_cmd;

reg [7:0]send_byte;
always @( posedge cclk )
	if( cmd_ready && (state==STATE_CATCH_SEND_BYTE || state==STATE_CATCH_SEND_BYTE1) )
		send_byte <= in_cmd;

reg bus_reset;
reg bus_enable;
always @( posedge cclk or posedge rst )
begin
	if(rst)
	begin
		bus_reset  <= 1'b0;
		bus_enable <= 1'b0;
	end
	else
	if( state==STATE_BUS_CONTROL )
	begin
		bus_reset  <= in_cmd_[4];
		bus_enable <= in_cmd_[5];
	end
end

always @( posedge cclk )
begin
	case( state )
	STATE_IDLE: begin 
					if( ~in_empty )
						state <= STATE_READ_CMD;
				end
	STATE_READ_CMD: begin 
						state <= STATE_GOT_CMD;
				end
	STATE_GOT_CMD: begin 
						case( in_cmd[3:0] )
							CMD_GET_LINES: state <= STATE_READ_LINES;
							CMD_BUS_CTRL:  state <= STATE_BUS_CONTROL;
							CMD_WAIT_EOF:  state <= STATE_WAIT_EOF;
							CMD_SEND_PKT:  state <= STATE_WAIT_BIT0;
							CMD_READ_PKT:  state <= STATE_READ_DATA;
							CMD_AUTO_ACK:  state <= STATE_SEND_ACK_WAIT_BIT0;
						default:
							   state <= STATE_IDLE;
						endcase
				end
	STATE_READ_LINES: begin 
					state <= STATE_IDLE;
				end
	STATE_BUS_CONTROL: begin
					state <= STATE_IDLE;
				end
	STATE_WAIT_EOF: begin
					if( bit_impulse & eof )
						state <= STATE_WAIT_NO_EOF;
				end
	STATE_WAIT_NO_EOF: begin
					if( bit_impulse & (~eof) )
						state <= STATE_IDLE;
				end
	STATE_WAIT_BIT0: begin
					if( bit_impulse &(~eof) )
						state <= STATE_WAIT_BIT1;
				end
	STATE_WAIT_BIT1: begin
					if( bit_impulse )
						state <= STATE_FETCH_SEND_BYTE;
				end
	STATE_FETCH_SEND_BYTE: begin 
				state <= STATE_CATCH_SEND_BYTE;
				end
	STATE_CATCH_SEND_BYTE: begin
				if( start_pkt)
					state <= STATE_FETCH_SEND_BYTE1;
				end
	STATE_FETCH_SEND_BYTE1: begin 
				state <= STATE_CATCH_SEND_BYTE1;
				end
	STATE_CATCH_SEND_BYTE1: begin
					state <= STATE_SENDING;
				end
	STATE_SENDING: begin 
				if( show_next & num_bytes_sent<in_cmd_[7:4])
					state <= STATE_FETCH_SEND_BYTE1;
				else
				if( pkt_end )
					state <= STATE_IDLE;
				end
	STATE_SEND_ACK_WAIT_BIT0: begin
					//here we may decide to ACK or not to ACK and got to STATE_IDLE..
					//if recent received byte is 0x5A(NAK) then no need to auto-ACK
					if( last_recv_byte==8'h5A )
						state <= STATE_IDLE;
					else
					if( bit_impulse )
						state <= STATE_SEND_ACK_WAIT_BIT1;
				end

	STATE_SEND_ACK_WAIT_BIT1: begin
					if( bit_impulse )
						state <= STATE_SEND_ACK_80;
				end
	STATE_SEND_ACK_80: begin
						state <= STATE_SEND_ACK_D2;
				end
	STATE_SEND_ACK_D2: begin
					if(show_next)
						state <= STATE_IDLE;
				end
	STATE_WAIT_ACK: begin
					state <= STATE_IDLE;
				end
	STATE_READ_DATA: begin 
					state <= STATE_READ_DATA_ALL;
				end
	STATE_READ_DATA_ALL: begin 
					if( eof | eop_r )
						state <= STATE_COPY_TMP_PKT;
				end
	STATE_COPY_TMP_PKT: begin 
					state <= STATE_COPY_TMP_PKT2;
				end
	STATE_COPY_TMP_PKT2: begin 
					if( tmp_fifo_empty )
						state <= STATE_IDLE;
					else
						state <= STATE_COPY_TMP_PKT;
				end
	endcase
end

reg [3:0]num_bytes_sent;
always @( posedge cclk )
	if( state==STATE_GOT_CMD )
		num_bytes_sent<= 1;
	else
	if( start_pkt | show_next )
		num_bytes_sent <= num_bytes_sent+1;

wire start_pkt; assign start_pkt = (state==STATE_CATCH_SEND_BYTE) & bit_impulse;
wire pkt_end;

wire [7:0]actual_send_byte;
assign actual_send_byte = 
	(state==STATE_SEND_ACK_80) ? 8'h80 : //maybe auto-ack or real data from SW
	(state==STATE_SEND_ACK_D2) ? 8'hD2 : send_byte;

wire actual_start_pkt;
assign actual_start_pkt = start_pkt | (state==STATE_SEND_ACK_80);

wire actual_last_pkt_byte;
assign actual_last_pkt_byte = (num_bytes_sent==in_cmd_[7:4]) | (state==STATE_SEND_ACK_D2);

wire show_next;
ls_usb_send ls_usb_send_(
	.reset( rst ),
	.clk( cclk ),
	.bit_impulse( bit_impulse ),
	.eof( eof ),
	.sbyte( actual_send_byte ),  			//byte for send
	.start_pkt( actual_start_pkt ),		//start sending packet on that signal
	.last_pkt_byte( actual_last_pkt_byte ),			//mean send EOP at the end
	.cmd_reset( bus_reset ),
	.cmd_enable( bus_enable ),
	.dp( o_dp ),
	.dm( o_dm ),
	.bus_enable( o_oe ),
	.show_next( show_next ), 	//request for next sending byte in packet
	.pkt_end( pkt_end )		//mean that packet was sent
	);

wire [3:0]usb_rbyte_cnt;
ls_usb_recv ls_usb_recv_(
	.reset( rst ),
	.clk( cclk ),
	.dp( i_dp ),
	.dm( i_dm ),
	.enable( enable_recv ),
	.eop_r( eop_r ),
	.rdata( usb_rdata ),
	.rdata_ready( usb_rdata_ready ),
	.rbyte_cnt( usb_rbyte_cnt ),
	.eop_rfe( )
	);

reg [7:0]last_recv_byte;
always @(posedge cclk)
	if(usb_rdata_ready) 
		last_recv_byte <= usb_rdata;

reg eop_r_;
always @(posedge cclk)
	eop_r_ <= eop_r;
wire got_recv_pkt_length;
assign got_recv_pkt_length = ((eop_r_==1'b0) && (eop_r==1'b1));

endmodule

/* S-box using all normal bases */
/*   case # 4 : [d^16, d], [alpha^8, alpha^2], [Omega^2, Omega] */
/*   beta^8 = N^2*alpha^2, N = w^2 */
/*   optimized using OR gates and NAND gates */

/* square in GF(2^2), using normal basis [Omega^2,Omega] */
/* inverse is the same as square in GF(2^2), using any normal basis */
module GF_SQ_2 ( A, Q );
    input  [1:0] A;
    output [1:0] Q;

    assign Q = { A[0], A[1] };
endmodule

/* scale by w = Omega in GF(2^2), using normal basis [Omega^2,Omega] */
module GF_SCLW_2 ( A, Q );
    input  [1:0] A;
    output [1:0] Q;

    assign Q = { (A[1] ^ A[0]), A[1] };
endmodule

/* scale by w^2 = Omega^2 in GF(2^2), using normal basis [Omega^2,Omega] */
module GF_SCLW2_2 ( A, Q );
    input  [1:0] A;
    output [1:0] Q;

    assign Q = { A[0], (A[1] ^ A[0]) };
endmodule

/* multiply in GF(2^2), shared factors, using normal basis [Omega^2,Omega] */
module GF_MULS_2 ( A, ab, B, cd, Q );
    input  [1:0] A;
    input  ab;
    input  [1:0] B;
    input  cd;
    output [1:0] Q;
    wire   abcd, p, q;

    assign abcd = ~(ab & cd);  /* note: ~& syntax for NAND won't compile */
    assign p = (~(A[1] & B[1])) ^ abcd;
    assign q = (~(A[0] & B[0])) ^ abcd;
    assign Q = { p, q };
endmodule

/* multiply & scale by N in GF(2^2), shared factors, basis [Omega^2,Omega] */
module GF_MULS_SCL_2 ( A, ab, B, cd, Q );
    input  [1:0] A;
    input  ab;
    input  [1:0] B;
    input  cd;
    output [1:0] Q;
    wire   t, p, q;

    assign t = ~(A[0] & B[0]);  /* note: ~& syntax for NAND won't compile */
    assign p = (~(ab & cd)) ^ t;
    assign q = (~(A[1] & B[1])) ^ t;
    assign Q = { p, q };
endmodule

/* inverse in GF(2^4)/GF(2^2), using normal basis [alpha^8, alpha^2] */
module GF_INV_4 ( A, Q );
    input  [3:0] A;
    output [3:0] Q;
    wire   [1:0] a, b, c, d, p, q;
    wire   sa, sb, sd;   /* for shared factors in multipliers */

    assign a = A[3:2];
    assign b = A[1:0];
    assign sa = a[1] ^ a[0];
    assign sb = b[1] ^ b[0];
/* optimize this section as shown below
    GF_MULS_2 abmul(a, sa, b, sb, ab);
    GF_SQ_2 absq( (a ^ b), ab2);
    GF_SCLW2_2 absclN( ab2, ab2N);
    GF_SQ_2 dinv( (ab ^ ab2N), d);
*/
    assign c = {   /* note: ~| syntax for NOR won't compile */
      ~(a[1] | b[1]) ^ (~(sa & sb)) ,
      ~(sa | sb) ^ (~(a[0] & b[0])) };
    GF_SQ_2 dinv( c, d);
/*  of optimization */
    assign sd = d[1] ^ d[0];
    GF_MULS_2 pmul(d, sd, b, sb, p);
    GF_MULS_2 qmul(d, sd, a, sa, q);
    assign Q = { p, q };
endmodule

/* square & scale by nu in GF(2^4)/GF(2^2), normal basis [alpha^8, alpha^2] */
/*   nu = beta^8 = N^2*alpha^2, N = w^2 */
module GF_SQ_SCL_4 ( A, Q );
    input  [3:0] A;
    output [3:0] Q;
    wire   [1:0] a, b, ab2, b2, b2N2;

    assign a = A[3:2];
    assign b = A[1:0];
    GF_SQ_2 absq(a ^ b,ab2);
    GF_SQ_2 bsq(b,b2);
    GF_SCLW_2 bmulN2(b2,b2N2);
    assign Q = { ab2, b2N2 };
endmodule

/* multiply in GF(2^4)/GF(2^2), shared factors, basis [alpha^8, alpha^2] */
module GF_MULS_4 ( A, a, Al, Ah, aa, B, b, Bl, Bh, bb, Q );
    input  [3:0] A;
    input  [1:0] a;
    input        Al;
    input        Ah;
    input        aa;
    input  [3:0] B;
    input  [1:0] b;
    input        Bl;
    input        Bh;
    input        bb;
    output [3:0] Q;
    wire   [1:0] ph, pl, ps, p;
    wire         t;

    GF_MULS_2 himul(A[3:2], Ah, B[3:2], Bh, ph);
    GF_MULS_2 lomul(A[1:0], Al, B[1:0], Bl, pl);
    GF_MULS_SCL_2 summul( a, aa, b, bb, p);
    assign Q = { (ph ^ p), (pl ^ p) };
endmodule

/* inverse in GF(2^8)/GF(2^4), using normal basis [d^16, d] */
module GF_INV_8 ( A, Q );
    input  [7:0] A;
    output [7:0] Q;
    wire   [3:0] a, b, c, d, p, q;
    wire   [1:0] sa, sb, sd, t;   /* for shared factors in multipliers */
    wire al, ah, aa, bl, bh, bb, dl, dh, dd;   /* for shared factors */
    wire c1, c2, c3;   /* for temp var */

    assign a = A[7:4];
    assign b = A[3:0];
    assign sa = a[3:2] ^ a[1:0];
    assign sb = b[3:2] ^ b[1:0];
    assign al = a[1] ^ a[0];
    assign ah = a[3] ^ a[2];
    assign aa = sa[1] ^ sa[0];
    assign bl = b[1] ^ b[0];
    assign bh = b[3] ^ b[2];
    assign bb = sb[1] ^ sb[0];
/* optimize this section as shown below
    GF_MULS_4 abmul(a, sa, al, ah, aa, b, sb, bl, bh, bb, ab);
    GF_SQ_SCL_4 absq( (a ^ b), ab2);
    GF_INV_4 dinv( (ab ^ ab2), d);
*/
    assign c1 = ~(ah & bh);
    assign c2 = ~(sa[0] & sb[0]);
    assign c3 = ~(aa & bb);
    assign c = {   /* note: ~| syntax for NOR won't compile */
      (~(sa[0] | sb[0]) ^ (~(a[3] & b[3]))) ^ c1 ^ c3 ,
      (~(sa[1] | sb[1]) ^ (~(a[2] & b[2]))) ^ c1 ^ c2 ,
      (~(al | bl) ^ (~(a[1] & b[1]))) ^ c2 ^ c3 ,
      (~(a[0] | b[0]) ^ (~(al & bl))) ^ (~(sa[1] & sb[1])) ^ c2 };
    GF_INV_4 dinv( c, d);
/* end of optimization */
    assign sd = d[3:2] ^ d[1:0];
    assign dl = d[1] ^ d[0];
    assign dh = d[3] ^ d[2];
    assign dd = sd[1] ^ sd[0];
    GF_MULS_4 pmul(d, sd, dl, dh, dd, b, sb, bl, bh, bb, p);
    GF_MULS_4 qmul(d, sd, dl, dh, dd, a, sa, al, ah, aa, q);
    assign Q = { p, q };
endmodule

/* MUX21I is an inverting 2:1 multiplexor */
module MUX21I ( A, B, s, Q );
    input        A;
    input        B;
    input        s;
    output       Q;
    assign Q = ~ ( s ? A : B );  /* mock-up for FPGA implementation */
endmodule

/* select and invert (NOT) byte, using MUX21I */
module SELECT_NOT_8 ( A, B, s, Q );
    input  [7:0] A;
    input  [7:0] B;
    input        s;
    output [7:0] Q;
    MUX21I m7(A[7],B[7],s,Q[7]);
    MUX21I m6(A[6],B[6],s,Q[6]);
    MUX21I m5(A[5],B[5],s,Q[5]);
    MUX21I m4(A[4],B[4],s,Q[4]);
    MUX21I m3(A[3],B[3],s,Q[3]);
    MUX21I m2(A[2],B[2],s,Q[2]);
    MUX21I m1(A[1],B[1],s,Q[1]);
    MUX21I m0(A[0],B[0],s,Q[0]);
endmodule

/* find either Sbox or its inverse in GF(2^8), by Canright Algorithm */
module bSbox ( A, encrypt, Q );
    input  [7:0] A;
    input        encrypt;  /* 1 for Sbox, 0 for inverse Sbox */
    output [7:0] Q;
    wire   [7:0] B, C, D, X, Y, Z;
    wire R1, R2, R3, R4, R5, R6, R7, R8, R9;
    wire T1, T2, T3, T4, T5, T6, T7, T8, T9, T10;

/* change basis from GF(2^8) to GF(2^8)/GF(2^4)/GF(2^2) */
/* combine with bit inverse matrix multiply of Sbox */
assign  R1  = A[7] ^ A[5] ;
assign  R2  = A[7] ~^ A[4] ;
assign  R3  = A[6] ^ A[0] ;
assign  R4  = A[5] ~^  R3  ;
assign  R5  = A[4] ^  R4  ;
assign  R6  = A[3] ^ A[0] ;
assign  R7  = A[2] ^  R1  ;
assign  R8  = A[1] ^  R3  ;
assign  R9  = A[3] ^  R8  ;
assign B[7] =  R7  ~^  R8  ;
assign B[6] =  R5  ;
assign B[5] = A[1] ^  R4  ;
assign B[4] =  R1  ~^  R3  ;
assign B[3] = A[1] ^  R2  ^  R6  ;
assign B[2] = ~ A[0] ;
assign B[1] =  R4  ;
assign B[0] = A[2] ~^  R9  ;
assign Y[7] =  R2  ;
assign Y[6] = A[4] ^  R8  ;
assign Y[5] = A[6] ^ A[4] ;
assign Y[4] =  R9  ;
assign Y[3] = A[6] ~^  R2  ;
assign Y[2] =  R7  ;
assign Y[1] = A[4] ^  R6  ;
assign Y[0] = A[1] ^  R5  ;
    SELECT_NOT_8 sel_in( B, Y, encrypt, Z );
    GF_INV_8 inv( Z, C );
/* change basis back from GF(2^8)/GF(2^4)/GF(2^2) to GF(2^8) */
assign  T1  = C[7] ^ C[3] ;
assign  T2  = C[6] ^ C[4] ;
assign  T3  = C[6] ^ C[0] ;
assign  T4  = C[5] ~^ C[3] ;
assign  T5  = C[5] ~^  T1  ;
assign  T6  = C[5] ~^ C[1] ;
assign  T7  = C[4] ~^  T6  ;
assign  T8  = C[2] ^  T4  ;
assign  T9  = C[1] ^  T2  ;
assign  T10  =  T3  ^  T5  ;
assign D[7] =  T4  ;
assign D[6] =  T1  ;
assign D[5] =  T3  ;
assign D[4] =  T5  ;
assign D[3] =  T2  ^  T5  ;
assign D[2] =  T3  ^  T8  ;
assign D[1] =  T7  ;
assign D[0] =  T9  ;
assign X[7] = C[4] ~^ C[1] ;
assign X[6] = C[1] ^  T10  ;
assign X[5] = C[2] ^  T10  ;
assign X[4] = C[6] ~^ C[1] ;
assign X[3] =  T8  ^  T9  ;
assign X[2] = C[7] ~^  T7  ;
assign X[1] =  T6  ;
assign X[0] = ~ C[2] ;
    SELECT_NOT_8 sel_out( D, X, encrypt, Q );
endmodule

/* test program: put Sbox output into register */
module sbox ( X, clk, Y );
    input  [7:0] X;
    output reg [7:0] Y;
    input  clk;

    wire   [7:0] O;

    bSbox sbe(X,1'b1,O);

   always @(posedge clk)
   begin
      Y = O;
   end

endmodule

