module Y (
    input clk, // data read/written on positive clock edges
    input reset, // reset all registers to a certain value
    inout [15:0] DATA,  // in and out from bus line
    output [15:0] REG_OUT_Y,  // for debugging, to RAM
    input Y_in,
    input Y_out,
    input Y_offset_in
);

// instantiation template 
/*
Y Y_inst0 (
    .clk(),
    .reset(), 
    .DATA(), 
    .REG_OUT_Y(),
    .Y_in(),
    .Y_out(),
    .Y_offset_in()
);
*/

reg [15:0] r;

// input from bus, or from bus but offset bits sign extended
always @(posedge clk) begin
    if (reset) begin
        r <= 0;
    end else if (Y_in) begin
        r <= DATA;
    end else if (Y_offset_in) begin
        r[8:0] <= DATA[8:0];
        r[15:9] <= 0;
    end
end

// if Y_out, r is driven to data port, else no connection (high impedance)
assign DATA = (Y_out)? r : 16'bZZZZZZZZZZZZZZZZ;
assign REG_OUT_Y = (Y_in)? DATA : r;

endmodule

`timescale 1ns / 1ps


module WB(
	input clk,memhazard,
	input wena,//写使能
	input [4:0] rs1,rs2,wrd,
	input [31:0] wdata,//写数据
	output reg [31:0] rd1,rd2
    );
	reg [31:0] rf[31:0];//深度为32的寄存器
	always @(posedge clk) begin
		if(memhazard==1'b1)begin
			rd1<=rd1;
			rd2<=rd2;

		else begin
			if(wena) begin
				rf[wrd] <= wdata;
			end
			if(rs1==5'bx)rd1<=32'bx;
			else if(rs1==5'b0)rd1<=32'b0;
			else if(rs1==wrd)rd1<=wdata;
			else rd1<=rf[rs1];

			if(rs2==5'bx)rd2<=32'bx;
			else if(rs2==5'b0)rd2<=32'b0;
			else if(rs2==wrd)rd2<=wdata;
			else rd2<=rf[rs2];
		end
	end

endmodule

//----------------------------------------------------------------------------
// Wishbone DDR Controller
// 
// (c) Joerg Bornschein (<jb@capsec.org>)
//----------------------------------------------------------------------------

module dpram
#(
	parameter adr_width = 9,
	parameter dat_width = 36
) (
	input                       clk,
	// Port 0
	input      [adr_width-1:0]  adr0,
	input                       we0,
	input      [dat_width-1:0]  din0,
	output reg [dat_width-1:0]  dout0,
	// Port 1
	input      [adr_width-1:0]  adr1,
	input                       we1,
	input      [dat_width-1:0]  din1,
	output reg [dat_width-1:0]  dout1
);

parameter depth = (1 << adr_width);

// actual ram 
reg [dat_width-1:0] ram [0:depth-1];

//------------------------------------------------------------------
// Syncronous Dual Port RAM Access
//------------------------------------------------------------------
always @(posedge clk)
begin
	// Frst port
	if (we0) 
		ram[adr0] <= din0;

	dout0 <= ram[adr0];
end


always @(posedge clk)
begin
	// Second port
	if (we1) 
		ram[adr1] <= din1;

	dout1 <= ram[adr1];
end

//------------------------------------------------------------------
// Initialize content to Zero
//------------------------------------------------------------------
integer i;

initial 
begin
	for(i=0; i<depth; i=i+1) 
		ram[i] <= 'b0;
end

endmodule

