//-----------------------------------------------------------------------------
// demultiplex phy nibbles
//-----------------------------------------------------------------------------


module rmii_recv (
  input reset, 

  //receive: data and active are valid at posedge of clock
  input  clock, 
  output [7:0] data,
  output active,

  //hardware pins
  input  PHY_CLK50,
  input  [1:0]PHY_RX,     
  input  PHY_CRS
  );

//-----------------------------------------------------------------------------
//          de-multiplex nibbles 
//-----------------------------------------------------------------------------
reg [7:0] shift_reg;
reg [3:0] crs;

always @(posedge PHY_CLK50)
begin
   shift_reg <= { PHY_RX, shift_reg[7:2] };
   crs <= { PHY_CRS & ~reset, crs[3:1]};
end



//-----------------------------------------------------------------------------
//          clock recovery and data synchronization
//-----------------------------------------------------------------------------
reg idle = 1'b1;
reg [1:0] cnt = 2'd3;
reg [7:0] data_sync;

always @(posedge PHY_CLK50) 
   if(idle)
   begin
      if(crs == 4'b1111 && shift_reg == 8'h55) 
      begin
         idle <= 1'b0;
         data_sync <= shift_reg;
      end
      cnt <= 2'd3;
   end
   else
   begin
      if(cnt == 2'b0)
      begin
         if(crs != 4'b0000/*crs == 4'b1111 || crs == 4'b0101 || crs == 4'b0111*/)
            data_sync <= shift_reg;
         else
            idle <= 1'b1;
      end 
      cnt <= cnt - 2'b1;
   end  


//-----------------------------------------------------------------------------
//                          preamble detector
//-----------------------------------------------------------------------------
localparam MIN_PREAMBLE_LENGTH = 3'd5;

reg [2:0] preamble_cnt;
reg payload_coming = 0;
//reg data_coming;

assign active = ~idle & payload_coming;
assign data = data_sync;

always @(posedge clock) 
begin
  if (idle) 
  begin 
      //RX-DV low, nothing is being received
      payload_coming <= 1'b0; 
      preamble_cnt <= MIN_PREAMBLE_LENGTH; 
  end
  else if (!payload_coming) 
    //RX-DV high, but payload is not being received yet
    //count preamble bytes
    if (data_sync == 8'h55) 
    begin 
      if (preamble_cnt != 0) preamble_cnt <= preamble_cnt - 3'd1; 
    end
    else if ((preamble_cnt == 0) && (data_sync == 8'hD5)) payload_coming <= 1'b1;
    //wrong byte received, reset preamble byte count
    else preamble_cnt <= MIN_PREAMBLE_LENGTH;

   //data_coming <= ~idle;

   //data <= data_sync;

end      

endmodule

// ECE:3350 SISC processor project
// instruction register

`timescale 1ns/100ps

module ir (clk, ir_load, read_data, instr);

  /*
   *  INSTRUCTION REGISTER - ir.v
   *
   *  Inputs:
   *   - clk: System clock; positive edge active
   *   - ir_load: if ir_load is = 1, the IR is loaded with read_data
   *   - read_data (32 bits): the 32 bit instruction from instruction memory
   *
   *  Outputs:
   *   - instr (32 bits): the 32 bit saved instruction
   *
   */

  input         clk;
  input         ir_load;
  input  [31:0] read_data;
  output [31:0] instr;

  wire          clk;
  wire          ir_load;
  wire   [31:0] read_data;
  reg    [31:0] instr;

  // instruction register

  initial
    instr <= 32'h00000000;

  always @(posedge clk)
    if (ir_load == 1'b1)
      instr <= read_data;


endmodule

module uart_rx
#(
	parameter CLK_FRE = 50,      //clock frequency(Mhz)
	parameter BAUD_RATE = 115200 //serial baud rate
)
(
	input                        clk,              //clock input
	input                        rst_n,            //asynchronous reset input, low active 
	output reg [55:0]             rx_data,          //received serial data
	output reg 					 light,
	input                        rx_data_ready,    //data receiver module ready
	input                        rx_pin            //serial data input
);
//calculates the clock cycle for baud rate 
localparam                       CYCLE = CLK_FRE * 1000000 / BAUD_RATE;
//state machine code
localparam                       S_IDLE      = 1;
localparam                       S_START     = 2; //start bit
localparam                       S_REC_BYTE  = 3; //data bits
localparam                       S_STOP      = 4; //stop bit
localparam                       S_DATA      = 5;

reg[2:0]                         state;
reg[2:0]                         next_state;
reg                              rx_d0;            //delay 1 clock for rx_pin
reg                              rx_d1;            //delay 1 clock for rx_d0
wire                             rx_negedge;       //negedge of rx_pin
reg[7:0]                         rx_bits;          //temporary storage of received data
reg[15:0]                        cycle_cnt;        //baud counter
reg[2:0]                         bit_cnt;          //bit counter

assign rx_negedge = rx_d1 && ~rx_d0;

always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
	begin
		rx_d0 <= 1'b0;
		rx_d1 <= 1'b0;	

	else
	begin
		rx_d0 <= rx_pin;
		rx_d1 <= rx_d0;
	end
end


always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		state <= S_IDLE;
	else
		state <= next_state;
end

always@(*)
begin
	case(state)
		S_IDLE:
			if(rx_negedge)
				next_state <= S_START;
			else
				next_state <= S_IDLE;
		S_START:
			if(cycle_cnt == CYCLE - 1)//one data cycle 
				next_state <= S_REC_BYTE;
			else
				next_state <= S_START;
		S_REC_BYTE:
			if(cycle_cnt == CYCLE - 1  && bit_cnt == 3'd7)  //receive 8bit data
				next_state <= S_STOP;
			else
				next_state <= S_REC_BYTE;
		S_STOP:
			if(cycle_cnt == CYCLE/2 - 1)//half bit cycle,to avoid missing the next byte receiver
				next_state <= S_DATA;
			else
				next_state <= S_STOP;
		S_DATA:
			if(rx_data_ready)    //data receive complete
				next_state <= S_IDLE;
			else
				next_state <= S_DATA;
		default:
			next_state <= S_IDLE;
	endcase
end

reg rx_out_en;
always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		rx_out_en <= 1'b0;
	else if(state == S_STOP && next_state != state)
		rx_out_en <= 1'b1;
	else if(state == S_DATA && rx_data_ready)
		rx_out_en <= 1'b0;
end

reg rx_state = 0;
reg [7:0] rx_data_r;
always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		rx_data_r <= 8'd0;
	else if(state == S_STOP && next_state != state) begin
		rx_data_r <= rx_bits;//latch received data
	end
end

always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		begin
			bit_cnt <= 3'd0;
		end
	else if(state == S_REC_BYTE)
		if(cycle_cnt == CYCLE - 1)
			bit_cnt <= bit_cnt + 3'd1;
		else
			bit_cnt <= bit_cnt;
	else
		bit_cnt <= 3'd0;
end


always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		cycle_cnt <= 16'd0;
	else if((state == S_REC_BYTE && cycle_cnt == CYCLE - 1) || next_state != state)
		cycle_cnt <= 16'd0;
	else
		cycle_cnt <= cycle_cnt + 16'd1;	
end
//receive serial data bit data
always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
		rx_bits <= 8'd0;
	else if(state == S_REC_BYTE && cycle_cnt == CYCLE/2 - 1)
		rx_bits[bit_cnt] <= rx_pin;
	else
		rx_bits <= rx_bits; 
end

//
reg [2:0] rx_cnt = 0;
always@(posedge rx_out_en)
begin
	rx_cnt <= rx_cnt == 0? 6 : rx_cnt - 1;
end	
	// if (rx_data_r >= 8'h80) //字库
	// 	rx_data [55:48] <= rx_data_r - 8'h80;
	// else if(rx_data_r >= 8'h41)//A - Z 
	// 	rx_data [(rx_cnt * 8 - 1) -: 8] <= rx_data_r - 8'h41 + 8'D10;
	// else if(rx_data_r >= 8'h30)//0 - 9
	// 	rx_data [(rx_cnt * 8 - 1) -: 8] <= rx_data_r - 8'h30;	
	// else rx_data <= rx_data;
reg rx_r;
always@(posedge clk)
	rx_r <= rx_out_en;

always@(posedge rx_r)
	case (rx_cnt)
		3'd6:begin rx_data [55:48] <= {1'b0,rx_data_r[6:0]} - 8'h40; light <= rx_data_r[7]; end
		3'd5:rx_data [47:40] <= rx_data_r - 8'D55; //- 8'h41 + 8'D10;
		3'd4:
			if(rx_data_r >= 8'h41 )//A - Z 
				rx_data [39:32] <= {3'B000 ,rx_data_r[4:0]} + 8'D9; //- 8'h41 + 8'D10;
			else if(rx_data_r >= 8'h30)//0 - 9
				rx_data [39:32] <= {4'B0000,rx_data_r[3:0]};	
		3'd3:
			if(rx_data_r >= 8'h41 )//A - Z 
				rx_data [31:24] <= {3'B000 ,rx_data_r[4:0]} + 8'D9; //- 8'h41 + 8'D10;
			else if(rx_data_r >= 8'h30)//0 - 9
				rx_data [31:24] <= {4'B0000,rx_data_r[3:0]};	
		3'd2:
			if(rx_data_r >= 8'h41 )//A - Z 
				rx_data [23:16] <= {3'B000 ,rx_data_r[4:0]} + 8'D9; //- 8'h41 + 8'D10;
			else if(rx_data_r >= 8'h30)//0 - 9
				rx_data [23:16] <= {4'B0000,rx_data_r[3:0]};	
		3'd1:
			if(rx_data_r >= 8'h41 )//A - Z 
				rx_data [15: 8] <= {3'B000 ,rx_data_r[4:0]} + 8'D9; //- 8'h41 + 8'D10;
			else if(rx_data_r >= 8'h30)//0 - 9
				rx_data [15: 8] <= {4'B0000,rx_data_r[3:0]};	
		3'd0:
			if(rx_data_r >= 8'h41 )//A - Z 
				rx_data [ 7: 0] <= {3'B000 ,rx_data_r[4:0]} + 8'D9; //- 8'h41 + 8'D10;
			else if(rx_data_r >= 8'h30)//0 - 9
				rx_data [ 7: 0] <= {4'B0000,rx_data_r[3:0]};	

		default : rx_data <= rx_data;
	endcase

endmodule

module
LU (S0,S1,X,Y,F3);
//S0,S1 are the select bases
input X,Y,S0,S1;
output F3;
wire X0,X1,X2,X3;
and G1(X0,X,Y);
//if S0=S1=0 then we have the ‘and’ of our inputs(X,Y) as an output
or G2(X1,X,Y);
//if S1=0 S0=1 then we have the ‘or’ of our inputs(X,Y) as an output
not G3(X,X);
//if S1=1 0=0 then we have the ‘not’ of X
xor G4(X3,X,Y);
//if S0=S1=1 then we have the ‘xor’ of our inputs(X,Y) as an output
MUX_4_1 m1(S0,S1,X0,X1,X2,X3,F3);
Endmodule

module mux10 (
  input [3:0] S,
  input [7:0] I0,
  input [7:0] I1,
  input [7:0] I2,
  input [7:0] I3,
  input [7:0] I4,
  input [7:0] I5,
  input [7:0] I6,
  input [7:0] I7,
  input [7:0] I8,
  input [7:0] I9,
  output reg [7:0] Z
);

always @(*) begin
  case (S)
    4'd0: Z = I0;
    4'd1: Z = I1;
    4'd2: Z = I2;
    4'd3: Z = I3;
    4'd4: Z = I4;
    4'd5: Z = I5;
    4'd6: Z = I6;
    4'd7: Z = I7;
    4'd8: Z = I8;
    4'd9: Z = I9;
    default: Z = 0;
  endcase
end

endmodule

module CLK_GATE
(
input  E       ,
input  CK      ,
input test_en  ,
output ECK     
);

reg latch_out ;

always @(CK or E)
begin
	if(!CK)
	  begin
    latch_out <= E;
	  end	
end


assign ECK = CK && latch_out ;



